import React, { useState, useEffect } from 'react';
import { X, Save, User, Mail, Phone, MapPin, Hash, Star } from 'lucide-react';
import { Member, MemberStage } from '../types';
import { STAGES } from '../constants';

interface MemberModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (member: Partial<Member>) => void;
  initialData?: Member | null;
}

const MemberModal: React.FC<MemberModalProps> = ({ isOpen, onClose, onSave, initialData }) => {
  const [formData, setFormData] = useState<Partial<Member>>({
    name: '',
    email: '',
    phone: '',
    stage: MemberStage.VISITOR,
    religion: '',
    address: '',
    channel: 'MANUAL',
    engagement_score: 50
  });

  useEffect(() => {
    if (initialData) {
      setFormData(initialData);
    } else {
      setFormData({
        name: '',
        email: '',
        phone: '',
        stage: MemberStage.VISITOR,
        religion: '',
        address: '',
        channel: 'MANUAL',
        engagement_score: 50
      });
    }
  }, [initialData, isOpen]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-white w-full max-w-xl rounded-[32px] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-indigo-50/30">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-indigo-600 rounded-xl text-white">
              <User className="w-5 h-5" />
            </div>
            <h3 className="text-xl font-black text-slate-800">
              {initialData ? 'Editar Membro' : 'Novo Membro'}
            </h3>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-white rounded-xl text-slate-400 transition-colors">
            <X className="w-6 h-6" />
          </button>
        </div>

        <form onSubmit={(e) => { e.preventDefault(); onSave(formData); }} className="p-8 space-y-5">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
            <div className="space-y-1 col-span-2">
              <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Nome Completo</label>
              <input 
                type="text" required
                className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
              />
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-black uppercase text-slate-400 ml-1">E-mail</label>
              <div className="relative">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                <input 
                  type="email"
                  className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none"
                  value={formData.email}
                  onChange={e => setFormData({...formData, email: e.target.value})}
                />
              </div>
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-black uppercase text-slate-400 ml-1">WhatsApp/Telefone</label>
              <div className="relative">
                <Phone className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                <input 
                  type="text"
                  className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none"
                  value={formData.phone}
                  onChange={e => setFormData({...formData, phone: e.target.value})}
                />
              </div>
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Estágio Atual</label>
              <select 
                className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none appearance-none"
                value={formData.stage}
                onChange={e => setFormData({...formData, stage: e.target.value as MemberStage})}
              >
                {STAGES.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}
              </select>
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Religião/Contexto</label>
              <input 
                type="text"
                placeholder="Ex: Católico, Sem religião"
                className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none"
                value={formData.religion}
                onChange={e => setFormData({...formData, religion: e.target.value})}
              />
            </div>

            <div className="space-y-1 col-span-2">
              <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Endereço / Localização</label>
              <div className="relative">
                <MapPin className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                <input 
                  type="text"
                  className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none"
                  value={formData.address}
                  onChange={e => setFormData({...formData, address: e.target.value})}
                />
              </div>
            </div>
          </div>

          <div className="pt-6 flex gap-3">
            <button 
              type="button"
              onClick={onClose}
              className="flex-1 py-4 bg-slate-100 text-slate-600 rounded-2xl font-bold hover:bg-slate-200 transition-all"
            >
              Cancelar
            </button>
            <button 
              type="submit"
              className="flex-[2] py-4 bg-indigo-600 text-white rounded-2xl font-bold shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all flex items-center justify-center gap-2"
            >
              <Save className="w-5 h-5" /> Salvar Membro
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default MemberModal;

import React, { useState, useEffect } from 'react';
import { X, Save, Calendar, Clock, MapPin, Tag } from 'lucide-react';
import { ScheduleEvent, EventType } from '../types';

interface EventModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (event: Partial<ScheduleEvent>) => void;
  initialData?: ScheduleEvent | null;
  defaultDate?: Date;
}

const EventModal: React.FC<EventModalProps> = ({ isOpen, onClose, onSave, initialData, defaultDate }) => {
  const [formData, setFormData] = useState<Partial<ScheduleEvent>>({
    title: '',
    description: '',
    type: EventType.SERVICE,
    location: '',
    start_date: new Date(),
    end_date: new Date(new Date().getTime() + 60 * 60 * 1000)
  });

  useEffect(() => {
    if (initialData) {
      setFormData(initialData);
    } else if (defaultDate) {
      setFormData({
        title: '',
        description: '',
        type: EventType.SERVICE,
        location: '',
        start_date: defaultDate,
        end_date: new Date(defaultDate.getTime() + 60 * 60 * 1000)
      });
    }
  }, [initialData, defaultDate, isOpen]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-white w-full max-w-xl rounded-[32px] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-indigo-50/30">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-indigo-600 rounded-xl text-white">
              <Calendar className="w-5 h-5" />
            </div>
            <h3 className="text-xl font-black text-slate-800">
              {initialData ? 'Editar Compromisso' : 'Novo Compromisso'}
            </h3>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-white rounded-xl text-slate-400 transition-colors">
            <X className="w-6 h-6" />
          </button>
        </div>

        <form onSubmit={(e) => { e.preventDefault(); onSave(formData); }} className="p-8 space-y-5">
          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Título do Evento</label>
            <input 
              type="text" required
              className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
              value={formData.title}
              onChange={e => setFormData({...formData, title: e.target.value})}
            />
          </div>

          <div className="grid grid-cols-2 gap-5">
            <div className="space-y-1">
              <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Tipo</label>
              <select 
                className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none appearance-none"
                value={formData.type}
                onChange={e => setFormData({...formData, type: e.target.value as EventType})}
              >
                {Object.values(EventType).map(type => (
                  <option key={type} value={type}>{type}</option>
                ))}
              </select>
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Local</label>
              <div className="relative">
                <MapPin className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                <input 
                  type="text"
                  className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none"
                  value={formData.location}
                  onChange={e => setFormData({...formData, location: e.target.value})}
                />
              </div>
            </div>
          </div>

          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Início</label>
            <div className="relative">
              <Clock className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
              <input 
                type="datetime-local" required
                className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none"
                value={formData.start_date instanceof Date ? formData.start_date.toISOString().slice(0, 16) : ''}
                onChange={e => setFormData({...formData, start_date: new Date(e.target.value)})}
              />
            </div>
          </div>

          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Descrição / Notas</label>
            <textarea 
              rows={3}
              className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none resize-none"
              value={formData.description}
              onChange={e => setFormData({...formData, description: e.target.value})}
            />
          </div>

          <div className="pt-6 flex gap-3">
            <button 
              type="button"
              onClick={onClose}
              className="flex-1 py-4 bg-slate-100 text-slate-600 rounded-2xl font-bold hover:bg-slate-200 transition-all"
            >
              Cancelar
            </button>
            <button 
              type="submit"
              className="flex-[2] py-4 bg-indigo-600 text-white rounded-2xl font-bold shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all flex items-center justify-center gap-2"
            >
              <Save className="w-5 h-5" /> Agendar Evento
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default EventModal;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Columns, 
  Zap, 
  Settings, 
  Bell, 
  Search, 
  User,
  LogOut,
  Menu,
  X,
  Shield,
  Mail,
  Key,
  Eye,
  EyeOff,
  ChevronDown,
  CalendarDays
} from 'lucide-react';
import KanbanBoard from './components/KanbanBoard';
import AnalyticsDashboard from './components/AnalyticsDashboard';
import AutomationSettings from './components/AutomationSettings';
import ScheduleModule from './components/ScheduleModule';
import MemberModal from './components/MemberModal';
import EventModal from './components/EventModal';
import { Member, MemberStage, SystemUser, UserRole, ScheduleEvent } from './types';
import { KoinoniaDB } from './services/db';

const navItems = [
  { id: 'analytics', label: 'Analytics', icon: <LayoutDashboard className="w-5 h-5" /> },
  { id: 'kanban', label: 'Pipeline', icon: <Columns className="w-5 h-5" /> },
  { id: 'agenda', label: 'Agenda', icon: <CalendarDays className="w-5 h-5" /> },
  { id: 'automation', label: 'Automação', icon: <Zap className="w-5 h-5" /> },
  { id: 'settings', label: 'Ajustes', icon: <Settings className="w-5 h-5" /> },
];

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loginMode, setLoginMode] = useState<'login' | 'register'>('login');
  const [showPassword, setShowPassword] = useState(false);
  const [activeTab, setActiveTab] = useState<any>('analytics');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [currentUser, setCurrentUser] = useState<SystemUser | null>(null);
  const [members, setMembers] = useState<Member[]>([]);
  const [events, setEvents] = useState<ScheduleEvent[]>([]);
  const [loginForm, setLoginForm] = useState({ name: '', email: '', church: '', password: '' });

  // Modals state
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [isEventModalOpen, setIsEventModalOpen] = useState(false);
  const [selectedMember, setSelectedMember] = useState<Member | null>(null);
  const [selectedEvent, setSelectedEvent] = useState<ScheduleEvent | null>(null);
  const [defaultEventDate, setDefaultEventDate] = useState<Date | undefined>();

  // Carregamento inicial
  useEffect(() => {
    setMembers(KoinoniaDB.getAllMembers());
    setEvents(KoinoniaDB.getAllEvents());

    const savedUser = localStorage.getItem('koinonia_session');
    if (savedUser) {
      setCurrentUser(JSON.parse(savedUser));
      setIsLoggedIn(true);
    }
  }, []);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const newUser: SystemUser = {
      id: Math.random().toString(36).substr(2, 9),
      name: loginForm.name || 'Líder Koinonia',
      email: loginForm.email || 'admin@koinonia.com',
      role: UserRole.ADMIN,
      church_id: loginForm.church || 'Igreja Central',
      permissions: ['all'],
      avatar: ''
    };

    setCurrentUser(newUser);
    localStorage.setItem('koinonia_session', JSON.stringify(newUser));
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    localStorage.removeItem('koinonia_session');
    setIsLoggedIn(false);
    setCurrentUser(null);
    setIsProfileOpen(false);
    setActiveTab('analytics');
  };

  // CRUD Membros
  const handleSaveMember = (memberData: Partial<Member>) => {
    let updatedMembers;
    if (memberData.id) {
      updatedMembers = members.map(m => m.id === memberData.id ? { ...m, ...memberData } as Member : m);
    } else {
      const newMember: Member = {
        ...memberData,
        id: Math.random().toString(36).substr(2, 9),
        registration_date: new Date(),
        last_activity: new Date(),
        engagement_score: 50,
        church_id: currentUser?.church_id || '1',
      } as Member;
      updatedMembers = [...members, newMember];
    }
    setMembers(updatedMembers);
    KoinoniaDB.saveMembers(updatedMembers);
    setIsMemberModalOpen(false);
    setSelectedMember(null);
  };

  const moveMember = (id: string, nextStage: MemberStage) => {
    const updated = members.map(m => m.id === id ? { ...m, stage: nextStage, last_activity: new Date() } : m);
    setMembers(updated);
    KoinoniaDB.saveMembers(updated);
  };

  // CRUD Eventos
  const handleSaveEvent = (eventData: Partial<ScheduleEvent>) => {
    let updatedEvents;
    if (eventData.id) {
      updatedEvents = events.map(e => e.id === eventData.id ? { ...e, ...eventData } as ScheduleEvent : e);
    } else {
      const newEvent: ScheduleEvent = {
        ...eventData,
        id: Math.random().toString(36).substr(2, 9),
        created_at: new Date(),
        church_id: currentUser?.church_id || '1',
      } as ScheduleEvent;
      updatedEvents = [...events, newEvent];
    }
    setEvents(updatedEvents);
    KoinoniaDB.saveEvents(updatedEvents);
    setIsEventModalOpen(false);
    setSelectedEvent(null);
    setDefaultEventDate(undefined);
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
        <div className="max-w-md w-full bg-white rounded-[40px] shadow-2xl shadow-indigo-100 border border-slate-100 overflow-hidden">
          <div className="p-10">
            <div className="flex justify-center mb-8">
              <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center shadow-lg shadow-indigo-200">
                <Shield className="w-8 h-8 text-white" />
              </div>
            </div>
            <h1 className="text-3xl font-black text-center text-slate-800 mb-2">Koinonia</h1>
            <p className="text-center text-slate-500 mb-8 font-medium">Gestão integrada de crescimento</p>

            <form onSubmit={handleLogin} className="space-y-4">
              {loginMode === 'register' && (
                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Nome Completo</label>
                  <div className="relative">
                    <User className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <input 
                      type="text" required
                      className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 transition-all outline-none"
                      placeholder="Ex: André Silva"
                      value={loginForm.name}
                      onChange={e => setLoginForm({...loginForm, name: e.target.value})}
                    />
                  </div>
                </div>
              )}

              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">E-mail</label>
                <div className="relative">
                  <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                  <input 
                    type="email" required
                    className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 transition-all outline-none"
                    placeholder="seu@email.com"
                    value={loginForm.email}
                    onChange={e => setLoginForm({...loginForm, email: e.target.value})}
                  />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Senha</label>
                <div className="relative">
                  <Key className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                  <input 
                    type={showPassword ? "text" : "password"} required
                    className="w-full pl-12 pr-12 py-4 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 transition-all outline-none"
                    placeholder="••••••••"
                    value={loginForm.password}
                    onChange={e => setLoginForm({...loginForm, password: e.target.value})}
                  />
                  <button 
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-indigo-600"
                  >
                    {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                  </button>
                </div>
              </div>

              <button 
                type="submit"
                className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-bold shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-[0.98] mt-4"
              >
                {loginMode === 'login' ? 'Acessar Sistema' : 'Criar minha conta'}
              </button>
            </form>

            <div className="mt-8 text-center">
              <button 
                onClick={() => setLoginMode(loginMode === 'login' ? 'register' : 'login')}
                className="text-sm font-bold text-indigo-600 hover:underline"
              >
                {loginMode === 'login' ? 'Não tem conta? Registre sua igreja' : 'Já possui conta? Faça login'}
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen bg-white overflow-hidden">
      <aside className={`bg-slate-900 transition-all duration-300 ${isSidebarOpen ? 'w-64' : 'w-20'} flex flex-col`}>
        <div className="p-6 flex items-center gap-4">
          <div className="w-10 h-10 bg-indigo-500 rounded-xl flex items-center justify-center shrink-0 shadow-lg shadow-indigo-500/20">
            <Shield className="w-6 h-6 text-white" />
          </div>
          {isSidebarOpen && <span className="font-black text-xl text-white tracking-tight">Koinonia</span>}
        </div>

        <nav className="flex-1 px-4 py-6 space-y-2">
          {navItems.map(item => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-4 px-4 py-3 rounded-2xl transition-all ${
                activeTab === item.id 
                  ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' 
                  : 'text-slate-400 hover:bg-slate-800 hover:text-white'
              }`}
            >
              {item.icon}
              {isSidebarOpen && <span className="font-bold text-sm">{item.label}</span>}
            </button>
          ))}
        </nav>

        <div className="p-4 border-t border-slate-800">
           <button 
            onClick={handleLogout}
            className="w-full flex items-center gap-4 px-4 py-3 rounded-2xl text-rose-400 hover:bg-rose-500/10 transition-all"
           >
             <LogOut className="w-5 h-5" />
             {isSidebarOpen && <span className="font-bold text-sm">Sair</span>}
           </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-slate-50 overflow-hidden relative">
        <header className="h-20 bg-white border-b border-slate-100 flex items-center justify-between px-8 shrink-0">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setIsSidebarOpen(!isSidebarOpen)}
              className="p-2 hover:bg-slate-50 rounded-xl text-slate-400"
            >
              {isSidebarOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}
            </button>
            <div className="relative group hidden md:block">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300 group-focus-within:text-indigo-500" />
              <input 
                type="text" 
                placeholder="Buscar membro, evento ou relatório..."
                className="pl-10 pr-4 py-2.5 bg-slate-50 border-transparent focus:bg-white focus:border-indigo-100 rounded-xl text-sm outline-none transition-all w-80"
              />
            </div>
          </div>

          <div className="flex items-center gap-6">
            <button className="relative p-2 text-slate-400 hover:text-indigo-600 transition-colors">
              <Bell className="w-5 h-5" />
              <span className="absolute top-2 right-2 w-2 h-2 bg-rose-500 rounded-full border-2 border-white"></span>
            </button>

            <div className="relative">
              <button 
                onClick={() => setIsProfileOpen(!isProfileOpen)}
                className="flex items-center gap-3 p-1.5 pl-3 rounded-2xl hover:bg-slate-50 transition-all border border-transparent hover:border-slate-100"
              >
                <div className="text-right hidden sm:block">
