import { Member, ScheduleEvent, SystemUser } from '../types';
import { INITIAL_MEMBERS, INITIAL_EVENTS } from '../constants';

const DB_KEYS = {
  MEMBERS: 'koinonia_members',
  EVENTS: 'koinonia_events',
  USER: 'koinonia_session'
};

export const KoinoniaDB = {
  getAllMembers: (): Member[] => {
    const data = localStorage.getItem(DB_KEYS.MEMBERS);
    if (!data) return INITIAL_MEMBERS;
    return JSON.parse(data).map((m: any) => ({
      ...m,
      last_activity: new Date(m.last_activity),
      registration_date: new Date(m.registration_date)
    }));
  },
  saveMembers: (members: Member[]) => {
    localStorage.setItem(DB_KEYS.MEMBERS, JSON.stringify(members));
  },
  getAllEvents: (): ScheduleEvent[] => {
    const data = localStorage.getItem(DB_KEYS.EVENTS);
    if (!data) return INITIAL_EVENTS;
    return JSON.parse(data).map((e: any) => ({
      ...e,
      start_date: new Date(e.start_date),
      end_date: new Date(e.end_date),
      created_at: new Date(e.created_at)
    }));
  },
  saveEvents: (events: ScheduleEvent[]) => {
    localStorage.setItem(DB_KEYS.EVENTS, JSON.stringify(events));
  }
};

