    localStorage.setItem('koinonia_session', JSON.stringify(newUser));
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    localStorage.removeItem('koinonia_session');
    setIsLoggedIn(false);
    setCurrentUser(null);
  };

  const handleSaveMember = (memberData: Partial<Member>) => {
    let updated;
    if (memberData.id) {
      updated = members.map(m => m.id === memberData.id ? { ...m, ...memberData } as Member : m);
    } else {
      const newMember: Member = {
        ...memberData,
        id: Math.random().toString(36).substr(2, 9),
        registration_date: new Date(),
        last_activity: new Date(),
        engagement_score: 50,
        church_id: currentUser?.church_id || 'default'
      } as Member;
      updated = [...members, newMember];
    }
    setMembers(updated);
    KoinoniaDB.saveMembers(updated);
    setIsMemberModalOpen(false);
    setSelectedMember(null);
  };

  const handleDeleteMember = (id: string) => {
    if (window.confirm('Tem certeza que deseja excluir este contato? Esta ação não pode ser desfeita.')) {
      const updated = members.filter(m => m.id !== id);
      setMembers(updated);
      KoinoniaDB.saveMembers(updated);
    }
  };

  const handleSaveEvent = (eventData: Partial<ScheduleEvent>) => {
    let updated;
    if (eventData.id) {
      updated = events.map(e => e.id === eventData.id ? { ...e, ...eventData } as ScheduleEvent : e);
    } else {
      const newEvent: ScheduleEvent = {
        ...eventData,
        id: Math.random().toString(36).substr(2, 9),
        created_at: new Date(),
        church_id: currentUser?.church_id || 'default'
      } as ScheduleEvent;
      updated = [...events, newEvent];
