import { Member, ScheduleEvent, SystemUser, Church } from '../types';
import { INITIAL_MEMBERS, INITIAL_EVENTS } from '../constants';

const DB_KEYS = {
  MEMBERS: 'koinonia_members',
  EVENTS: 'koinonia_events',
  USERS: 'koinonia_users',
  CHURCHES: 'koinonia_churches',
  SESSION: 'koinonia_session'
};

export const KoinoniaDB = {
  // Members
  getAllMembers: (): Member[] => {
    const data = localStorage.getItem(DB_KEYS.MEMBERS);
    if (!data) return INITIAL_MEMBERS;
    return JSON.parse(data).map((m: any) => ({
      ...m,
      last_activity: new Date(m.last_activity),
      registration_date: new Date(m.registration_date)
    }));
  },
  saveMembers: (members: Member[]) => {
    localStorage.setItem(DB_KEYS.MEMBERS, JSON.stringify(members));
  },

  // Events
  getAllEvents: (): ScheduleEvent[] => {
    const data = localStorage.getItem(DB_KEYS.EVENTS);
    if (!data) return INITIAL_EVENTS;
    return JSON.parse(data).map((e: any) => ({
      ...e,
      start_date: new Date(e.start_date),
      end_date: new Date(e.end_date),
      created_at: new Date(e.created_at)
    }));
  },
  saveEvents: (events: ScheduleEvent[]) => {
    localStorage.setItem(DB_KEYS.EVENTS, JSON.stringify(events));
  },

  // Users / Team
  getAllUsers: (): SystemUser[] => {
    const data = localStorage.getItem(DB_KEYS.USERS);
    return data ? JSON.parse(data) : [];
  },
  saveUsers: (users: SystemUser[]) => {
    localStorage.setItem(DB_KEYS.USERS, JSON.stringify(users));
  },

  // Churches
  getAllChurches: (): Church[] => {
    const data = localStorage.getItem(DB_KEYS.CHURCHES);
    return data ? JSON.parse(data) : [];
  },
  saveChurches: (churches: Church[]) => {
    localStorage.setItem(DB_KEYS.CHURCHES, JSON.stringify(churches));
  }
};

import React, { useState } from 'react';
import { Shield, Mail, Key, User, Church as ChurchIcon, ArrowRight, Eye, EyeOff } from 'lucide-react';
import { SystemUser, UserRole, Church } from '../types';
import { KoinoniaDB } from '../services/db';

interface LoginScreenProps {
  onLogin: (user: SystemUser) => void;
}

const LoginScreen: React.FC<LoginScreenProps> = ({ onLogin }) => {
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [showPass, setShowPass] = useState(false);
  const [form, setForm] = useState({
    name: '',
    email: '',
    password: '',
    churchName: '',
    phone: ''
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (mode === 'register') {
      const churchId = Math.random().toString(36).substr(2, 9);
      const userId = Math.random().toString(36).substr(2, 9);

      const newChurch: Church = {
        id: churchId,
        name: form.churchName,
        pastor_name: form.name,
        address: '',
        phone: form.phone,
        email: form.email,
        created_at: new Date()
      };

      const newUser: SystemUser = {
        id: userId,
        name: form.name,
        email: form.email,
        password: form.password,
        role: UserRole.ADMIN,
        church_id: churchId,
        permissions: ['all']
      };

      const churches = KoinoniaDB.getAllChurches();
      const users = KoinoniaDB.getAllUsers();

      KoinoniaDB.saveChurches([...churches, newChurch]);
      KoinoniaDB.saveUsers([...users, newUser]);

      onLogin(newUser);
    } else {
      const users = KoinoniaDB.getAllUsers();
