                  </div>
                  <button onClick={() => { setActiveTab('settings'); setIsProfileOpen(false); }} className="w-full text-left px-6 py-3 text-xs font-bold text-slate-600 hover:bg-slate-50 hover:text-indigo-600 transition-all">Perfil do Usuário</button>
                  <button onClick={handleLogout} className="w-full text-left px-6 py-3 text-xs font-bold text-rose-500 hover:bg-rose-50 transition-all">Sair do Koinonia</button>
                </div>
