  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!church) return;

    const churches = KoinoniaDB.getAllChurches();
    const index = churches.findIndex(c => c.id === church.id);

    let updatedChurches;
    if (index !== -1) {
      updatedChurches = [...churches];
      updatedChurches[index] = church;
    } else {
      updatedChurches = [...churches, church];
    }

    KoinoniaDB.saveChurches(updatedChurches);
    setIsEditing(false);
    alert('Os dados da sua igreja foram atualizados com sucesso!');
  };

  if (!church) {
    return (
      <div className="h-full flex items-center justify-center text-slate-400 font-bold uppercase tracking-widest p-8 text-center">
        Carregando dados da instituição...
      </div>
    );
  }

  return (
    <div className="p-8 space-y-8 overflow-y-auto h-full max-w-5xl mx-auto">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tighter uppercase">Minha Igreja</h2>
          <p className="text-slate-500 font-medium">Dados institucionais e configurações da comunidade.</p>
        </div>
        <button 
          onClick={() => setIsEditing(!isEditing)}
          className={`px-6 py-4 rounded-2xl font-black shadow-sm transition-all uppercase tracking-widest text-[10px] border ${
            isEditing 
              ? 'bg-rose-50 border-rose-100 text-rose-600 hover:bg-rose-100' 
              : 'bg-white border-slate-100 text-slate-600 hover:bg-slate-50'
          }`}
        >
          {isEditing ? 'Cancelar Edição' : 'Editar Informações'}
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm flex flex-col items-center">
            <div className="relative group">
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleImageUpload} 
                className="hidden" 
                accept="image/*"
              />
              <div className="w-32 h-32 bg-indigo-50 rounded-[32px] flex items-center justify-center text-indigo-300 border-2 border-dashed border-indigo-200 overflow-hidden relative shadow-inner">
                {church.logo_url ? (
                  <img src={church.logo_url} className="w-full h-full object-cover" alt="Logo" />
                ) : (
                  <ChurchIcon className="w-12 h-12" />
                )}

                {isEditing && church.logo_url && (
                  <button 
                    onClick={(e) => { e.stopPropagation(); removeLogo(); }}
                    className="absolute inset-0 bg-rose-500/80 flex items-center justify-center opacity-0 hover:opacity-100 transition-opacity text-white"
                  >
                    <Trash2 className="w-6 h-6" />
                  </button>
                )}
              </div>

              {isEditing && (
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="absolute bottom-[-10px] right-[-10px] p-3 bg-indigo-600 text-white rounded-2xl shadow-lg hover:bg-indigo-700 transition-all z-10"
                  title="Alterar Foto"
                >
                  <Camera className="w-4 h-4" />
                </button>
              )}
            </div>
            <h3 className="mt-6 text-xl font-black text-slate-800 text-center">{church.name}</h3>
            <p className="text-xs font-bold text-indigo-500 uppercase tracking-widest mt-1">Sede Administrativa</p>
          </div>

          <div className="bg-slate-900 p-8 rounded-[40px] shadow-xl text-white">
            <h4 className="text-xs font-black uppercase tracking-[0.2em] text-indigo-400 mb-4">Localização</h4>
            <div className="space-y-4">
               <div className="flex items-start gap-3 p-4 bg-slate-800 rounded-2xl">
                 <MapPin className="w-5 h-5 text-indigo-400 shrink-0 mt-0.5" />
                 <div>
                   <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Endereço Atual</p>
                   <p className="text-xs font-bold mt-1 text-slate-200 leading-relaxed">
                     {church.address ? `${church.address}, ${church.city || ''} - ${church.state || ''}` : 'Não informado'}
                   </p>
                 </div>
               </div>
            </div>
          </div>
        </div>

        <div className="lg:col-span-2">
          <form onSubmit={handleSave} className="bg-white p-10 rounded-[48px] border border-slate-100 shadow-sm space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2 md:col-span-2">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Nome Institucional</label>
                <input 
                  type="text" 
                  disabled={!isEditing}
                  className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 font-medium text-slate-800 disabled:opacity-60 transition-all"
                  value={church.name}
                  onChange={e => setChurch({...church, name: e.target.value})}
                  placeholder="Nome da sua igreja"
                />
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-2">CEP (Busca Automática)</label>
                <div className="relative">
                  <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                  <input 
                    type="text" 
                    disabled={!isEditing}
                    maxLength={9}
                    className="w-full pl-12 pr-12 py-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 font-medium text-slate-800 disabled:opacity-60 transition-all"
                    value={church.cep || ''}
                    onChange={e => {
                      const val = e.target.value;
                      setChurch({...church, cep: val});
                      handleCepLookup(val);
                    }}
                    placeholder="00000-000"
                  />
                  {isLoadingCep && <Loader2 className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-indigo-500 animate-spin" />}
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Cidade</label>
                <input 
                  type="text" 
                  disabled={!isEditing}
                  className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 font-medium text-slate-800 disabled:opacity-60 transition-all"
                  value={church.city || ''}
                  onChange={e => setChurch({...church, city: e.target.value})}
                  placeholder="Cidade"
                />
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Estado (UF)</label>
                <input 
                  type="text" 
                  disabled={!isEditing}
                  maxLength={2}
                  className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 font-medium text-slate-800 disabled:opacity-60 transition-all uppercase"
                  value={church.state || ''}
                  onChange={e => setChurch({...church, state: e.target.value})}
                  placeholder="UF"
                />
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Pastor Sênior</label>
                <input 
                  type="text" 
                  disabled={!isEditing}
                  className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 font-medium text-slate-800 disabled:opacity-60 transition-all"
                  value={church.pastor_name}
                  onChange={e => setChurch({...church, pastor_name: e.target.value})}
                  placeholder="Nome do pastor"
                />
              </div>

              <div className="space-y-2 md:col-span-2">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Logradouro e Bairro</label>
                <div className="relative">
                  <MapPin className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                  <input 
                    type="text" 
                    disabled={!isEditing}
                    className="w-full pl-12 pr-6 py-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 font-medium text-slate-800 disabled:opacity-60 transition-all"
                    value={church.address}
                    onChange={e => setChurch({...church, address: e.target.value})}
                    placeholder="Rua, Número, Bairro"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Telefone de Contato</label>
                <div className="relative">
                  <Phone className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                  <input 
                    type="text" 
                    disabled={!isEditing}
                    className="w-full pl-12 pr-6 py-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 font-medium text-slate-800 disabled:opacity-60 transition-all"
                    value={church.phone}
                    onChange={e => setChurch({...church, phone: e.target.value})}
                    placeholder="(00) 00000-0000"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-2">E-mail Institucional</label>
                <div className="relative">
                  <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                  <input 
                    type="email" 
                    disabled={!isEditing}
                    className="w-full pl-12 pr-6 py-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 font-medium text-slate-800 disabled:opacity-60 transition-all"
                    value={church.email}
                    onChange={e => setChurch({...church, email: e.target.value})}
                    placeholder="contato@igreja.com"
                  />
                </div>
              </div>
            </div>

            {isEditing && (
              <button 
                type="submit"
                className="w-full py-5 bg-indigo-600 text-white rounded-[24px] font-black shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all flex items-center justify-center gap-3 uppercase tracking-widest text-[10px] active:scale-[0.98]"
              >
                <Save className="w-5 h-5" /> Salvar Alterações Institucionais
              </button>
            )}
          </form>
        </div>
      </div>
    </div>
  );
};

export default ChurchModule;

export enum MemberStage {
  VISITOR = 'VISITOR',
  NEW_MEMBER = 'NEW_MEMBER',
  ACTIVE_MEMBER = 'ACTIVE_MEMBER',
  LEADER_IN_TRAINING = 'LEADER_IN_TRAINING',
  LEADER = 'LEADER'
}

export enum UserRole {
  ADMIN = 'ADMIN',
  PASTOR = 'PASTOR',
  LEADER = 'LEADER',
  RECEPTION = 'RECEPTION',
  VOLUNTEER = 'VOLUNTEER'
}

export enum EventType {
  SERVICE = 'SERVICE',
  MEETING = 'MEETING',
  EVENT = 'EVENT',
  FOLLOW_UP = 'FOLLOW_UP',
  VISIT = 'VISIT'
}

export interface Church {
  id: string;
  name: string;
  cep?: string;
  address: string;
  city?: string;
  state?: string;
  cnpj?: string;
  pastor_name: string;
  phone: string;
  email: string;
  logo_url?: string;
  created_at: Date;
}

export interface ScheduleEvent {
  id: string;
  title: string;
  description?: string;
  start_date: Date;
  end_date: Date;
  location?: string;
  type: EventType;
  church_id: string;
  member_id?: string;
  responsible_id?: string;
  created_at: Date;
}

export interface SystemUser {
  id: string;
  name: string;
  email: string;
  password?: string;
  whatsapp?: string;
  role: UserRole;
  duty?: string; // Novo campo para "Função"
  church_id: string;
  avatar?: string;
  permissions: string[];
}

export interface Member {
  id: string;
  name: string;
  email: string;
  phone: string;
  gender?: string;
  religion?: string;
  address?: string;
  stage: MemberStage;
  last_activity: Date;
  engagement_score: number; 
  church_id: string;
  responsible_leader_id?: string;
  registration_date: Date;
  channel: string;
  notes?: string;
}

import React, { useState, useEffect } from 'react';
import { Users, UserPlus, Shield, Mail, Trash2, Edit3, Key, X, Save, Briefcase, ChevronDown } from 'lucide-react';
import { SystemUser, UserRole } from '../types';
import { KoinoniaDB } from '../services/db';

const TeamModule: React.FC = () => {
  const [team, setTeam] = useState<SystemUser[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedUser, setSelectedUser] = useState<SystemUser | null>(null);

  // Form State
  const [formData, setFormData] = useState<Partial<SystemUser>>({
    name: '',
    email: '',
    password: '',
    role: UserRole.LEADER,
    duty: '',
  });

  useEffect(() => {
    setTeam(KoinoniaDB.getAllUsers());
  }, []);

  const openModal = (user?: SystemUser) => {
    if (user) {
      setSelectedUser(user);
      setFormData(user);
    } else {
      setSelectedUser(null);
      setFormData({
        name: '',
        email: '',
        password: '',
        role: UserRole.LEADER,
        duty: '',
      });
    }
    setIsModalOpen(true);
  };

  const handleSaveUser = (e: React.FormEvent) => {
    e.preventDefault();
    const users = KoinoniaDB.getAllUsers();
    let updatedUsers;

    if (selectedUser) {
      updatedUsers = users.map(u => u.id === selectedUser.id ? { ...u, ...formData } as SystemUser : u);
    } else {
      const newUser: SystemUser = {
        ...formData,
        id: Math.random().toString(36).substr(2, 9),
        church_id: 'default',
        permissions: ['standard'],
      } as SystemUser;
      updatedUsers = [...users, newUser];
    }

    KoinoniaDB.saveUsers(updatedUsers);
    setTeam(updatedUsers);
    setIsModalOpen(false);
  };

  const handleDeleteUser = (id: string) => {
    if (window.confirm('Tem certeza que deseja remover este líder da equipe?')) {
      const updatedUsers = team.filter(u => u.id !== id);
      KoinoniaDB.saveUsers(updatedUsers);
      setTeam(updatedUsers);
    }
  };

  const getRoleBadge = (role: UserRole) => {
    const styles = {
      [UserRole.ADMIN]: 'bg-indigo-100 text-indigo-700 border-indigo-200',
      [UserRole.PASTOR]: 'bg-purple-100 text-purple-700 border-purple-200',
      [UserRole.LEADER]: 'bg-emerald-100 text-emerald-700 border-emerald-200',
      [UserRole.VOLUNTEER]: 'bg-slate-100 text-slate-700 border-slate-200',
      [UserRole.RECEPTION]: 'bg-blue-100 text-blue-700 border-blue-200',
    };
    return (
      <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase border ${styles[role]}`}>
        {role}
      </span>
    );
  };

  return (
    <div className="p-8 space-y-8 overflow-y-auto h-full bg-slate-50/50">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tighter uppercase">Gestão de Equipe</h2>
          <p className="text-slate-500 font-medium">Controle de acessos e atribuições para líderes e voluntários.</p>
        </div>
        <button 
          onClick={() => openModal()}
          className="flex items-center gap-2 px-6 py-4 bg-indigo-600 text-white rounded-2xl font-black shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95 uppercase tracking-widest text-xs"
        >
          <UserPlus className="w-5 h-5" /> Adicionar Líder
        </button>
      </div>

      <div className="bg-white rounded-[40px] border border-slate-100 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50/50 border-b border-slate-100">
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Líder</th>
                <th className="px-6 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Nível de Acesso</th>
                <th className="px-6 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Função Ministerial</th>
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-right">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {team.map((user) => (
                <tr key={user.id} className="group hover:bg-indigo-50/30 transition-all">
                  <td className="px-10 py-5">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-2xl bg-slate-100 flex items-center justify-center text-slate-400 font-black shadow-inner group-hover:bg-indigo-600 group-hover:text-white transition-all">
                        {user.name[0]}
                      </div>
                      <div>
                        <p className="font-bold text-slate-800 group-hover:text-indigo-600 transition-colors">{user.name}</p>
                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">{user.email}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-5">
                    {getRoleBadge(user.role)}
                  </td>
                  <td className="px-6 py-5">
                    <div className="flex items-center gap-2 text-sm text-slate-600 font-bold italic">
                      <Briefcase className="w-4 h-4 text-indigo-400 shrink-0" />
                      {user.duty || <span className="text-slate-300 font-normal">Não definida</span>}
                    </div>
                  </td>
                  <td className="px-10 py-5">
                    <div className="flex items-center justify-end gap-3">
                      <button 
                        onClick={() => openModal(user)}
                        className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-white rounded-xl transition-all shadow-sm"
                        title="Editar"
                      >
                        <Edit3 className="w-4 h-4" />
                      </button>
                      <button 
                        onClick={() => handleDeleteUser(user.id)}
                        className="p-2 text-slate-400 hover:text-rose-600 hover:bg-white rounded-xl transition-all shadow-sm"
                        title="Remover"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {team.length === 0 && (
          <div className="py-20 text-center text-slate-300">
            <Users className="w-16 h-16 mx-auto opacity-20 mb-4" />
            <p className="font-black uppercase tracking-widest text-xs">Nenhum líder cadastrado</p>
          </div>
        )}
      </div>

      {/* Team Member Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-lg rounded-[48px] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-indigo-50/30">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-indigo-600 rounded-2xl text-white">
                  <Shield className="w-6 h-6" />
                </div>
                <div>
                  <h3 className="text-2xl font-black text-slate-800">
                    {selectedUser ? 'Editar Líder' : 'Novo Líder'}
                  </h3>
                  <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">Acesso ao Koinonia</p>
                </div>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-3 hover:bg-white rounded-2xl text-slate-400 transition-all">
                <X className="w-6 h-6" />
              </button>
            </div>

            <form onSubmit={handleSaveUser} className="p-10 space-y-6">
              <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Nome Completo</label>
                  <input 
                    type="text" required
                    className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 font-medium text-slate-800 outline-none transition-all"
                    placeholder="Ex: Pedro Alvares"
                    value={formData.name}
                    onChange={e => setFormData({...formData, name: e.target.value})}
                  />
                </div>

                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-2">E-mail de Acesso</label>
                  <div className="relative">
                    <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                    <input 
                      type="email" required
                      className="w-full pl-12 pr-6 py-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 font-medium text-slate-800 outline-none transition-all"
                      placeholder="seu@email.com"
                      value={formData.email}
                      onChange={e => setFormData({...formData, email: e.target.value})}
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Nível de Acesso</label>
                    <div className="relative">
                      <select 
                        className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 font-black text-[10px] uppercase tracking-widest text-indigo-600 outline-none appearance-none"
                        value={formData.role}
                        onChange={e => setFormData({...formData, role: e.target.value as UserRole})}
                      >
                        {Object.values(UserRole).map(role => (
                          <option key={role} value={role}>{role}</option>
                        ))}
                      </select>
                      <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300 pointer-events-none" />
                    </div>
                  </div>

                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Senha Temporária</label>
                    <div className="relative">
                      <Key className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                      <input 
                        type="password"
                        className="w-full pl-12 pr-6 py-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 font-medium text-slate-800 outline-none transition-all"
                        placeholder="••••••"
                        value={formData.password}
                        onChange={e => setFormData({...formData, password: e.target.value})}
                      />
                    </div>
                  </div>
                </div>

                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Função Ministerial (O que faz?)</label>
                  <div className="relative">
                    <Briefcase className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                    <input 
                      type="text"
                      className="w-full pl-12 pr-6 py-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 font-bold text-slate-800 outline-none transition-all"
                      placeholder="Ex: Líder de Louvor, Recepção, EBD..."
                      value={formData.duty}
                      onChange={e => setFormData({...formData, duty: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              <div className="pt-6 flex gap-4">
                <button 
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="flex-1 py-4 bg-slate-100 text-slate-600 rounded-2xl font-black uppercase tracking-widest text-[10px] hover:bg-slate-200 transition-all"
                >
                  Cancelar
                </button>
                <button 
                  type="submit"
