import React, { useState } from 'react';
import { Member, MemberStage, ScheduleEvent } from '../types';
import { STAGES } from '../constants';
import { generateHumanizedMessage } from '../services/geminiService';
import { MessageCircle, ArrowRight, Loader2, Mail, MapPin, History, ChevronRight, Phone } from 'lucide-react';

interface MemberCardProps {
  member: Member;
  events?: ScheduleEvent[];
  onMove?: (id: string, newStage: MemberStage) => void;
  onClick?: (member: Member) => void;
  onEditEvent?: (event: ScheduleEvent) => void;
}

const MemberCard: React.FC<MemberCardProps> = ({ member, events = [], onMove, onClick, onEditEvent }) => {
  const [isGenerating, setIsGenerating] = useState(false);

  const getScoreColor = (score: number) => {
    if (score > 80) return 'bg-emerald-500';
    if (score > 50) return 'bg-amber-500';
    return 'bg-rose-500';
  };

  const handleNextStage = (e: React.MouseEvent) => {
    e.stopPropagation();
    const currentIndex = STAGES.findIndex(s => s.id === member.stage);
    if (currentIndex < STAGES.length - 1 && onMove) {
      onMove(member.id, STAGES[currentIndex + 1].id as MemberStage);
    }
  };

  const handleGenerateMessage = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (isGenerating) return;
    setIsGenerating(true);
    const stageLabel = STAGES.find(s => s.id === member.stage)?.label || member.stage;
    try {
      const msg = await generateHumanizedMessage(
        member.name, 
        stageLabel, 
        "Contato caloroso de acompanhamento da liderança"
      );
      alert(`Mensagem Gerada para ${member.name}:\n\n${msg}`);
    } catch (err) {
      console.error(err);
    } finally {
      setIsGenerating(false);
    }
  };

  const memberEvents = events
    .filter(e => e.member_id === member.id)
    .sort((a, b) => b.start_date.getTime() - a.start_date.getTime())
    .slice(0, 2);

  const isAtLastStage = STAGES.findIndex(s => s.id === member.stage) === STAGES.length - 1;

  return (
    <div 
      onClick={() => onClick?.(member)}
      className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-all group cursor-pointer active:scale-[0.98] flex flex-col gap-4 relative overflow-hidden"
    >
      <div className={`absolute left-0 top-0 bottom-0 w-1 ${getScoreColor(member.engagement_score)}`} />

      <div className="flex justify-between items-start gap-3">
        <div className="flex-1 min-w-0">
          <h4 className="font-black text-slate-800 text-sm truncate leading-tight">{member.name}</h4>
          <p className="text-[10px] font-bold text-indigo-500 uppercase tracking-tighter mt-0.5">
            {member.religion || 'Religião não inf.'}
          </p>
        </div>
        <div className="flex -space-x-1 shrink-0">
          {member.channel === 'INSTAGRAM' && (
            <div className="w-5 h-5 rounded-full bg-pink-500 flex items-center justify-center text-white border border-white" title="Instagram">
              <span className="text-[8px] font-black">IG</span>
            </div>
          )}
          {member.channel === 'QR_CODE' && (
            <div className="w-5 h-5 rounded-full bg-blue-500 flex items-center justify-center text-white border border-white" title="QR Code">
              <span className="text-[8px] font-black">QR</span>
            </div>
          )}
        </div>
      </div>

      <div className="space-y-1.5">
        <div className="flex items-center gap-2 text-[10px] text-slate-500 font-medium">
          <Phone className="w-3 h-3 text-slate-300" />
          <span className="truncate">{member.phone || 'Sem fone'}</span>
        </div>
        <div className="flex items-start gap-2 text-[10px] text-slate-500 font-medium">
          <MapPin className="w-3 h-3 text-slate-300 shrink-0 mt-0.5" />
          <span className="line-clamp-1">{member.address || 'Sem endereço'}</span>
        </div>
      </div>

      {memberEvents.length > 0 && (
        <div className="bg-slate-50 p-2.5 rounded-xl space-y-2">
          <div className="flex items-center gap-1.5 text-[8px] font-black text-slate-400 uppercase tracking-widest">
            <History className="w-2.5 h-2.5" /> Últimas Atividades
          </div>
          <div className="space-y-1">
            {memberEvents.map(event => (
              <button 
                key={event.id}
                onClick={(e) => { e.stopPropagation(); onEditEvent?.(event); }}
                className="w-full flex items-center justify-between text-left group/ev"
              >
                <span className="text-[9px] font-bold text-slate-600 truncate">{event.title}</span>
                <ChevronRight className="w-2.5 h-2.5 text-slate-300 group-hover/ev:text-indigo-500" />
              </button>
            ))}
          </div>
        </div>
      )}

      <div className="flex items-center justify-between pt-1 mt-auto">
        <div className="flex flex-col">
          <p className="text-[9px] font-black text-slate-400 uppercase">Engajamento</p>
          <p className="text-xs font-black text-slate-800">{member.engagement_score}%</p>
        </div>

        <div className="flex gap-1.5">
          <button 
            onClick={handleGenerateMessage}
            disabled={isGenerating}
            className="w-8 h-8 rounded-xl bg-emerald-50 text-emerald-600 hover:bg-emerald-600 hover:text-white disabled:opacity-50 transition-all flex items-center justify-center"
            title="Gerar Mensagem IA"
          >
            {isGenerating ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <MessageCircle className="w-3.5 h-3.5" />}
          </button>
          <button 
            onClick={handleNextStage}
            disabled={isAtLastStage}
            className="w-8 h-8 rounded-xl bg-slate-50 text-slate-600 hover:bg-indigo-600 hover:text-white disabled:opacity-30 transition-all flex items-center justify-center"
            title={isAtLastStage ? "Estágio Final" : "Avançar Jornada"}
          >
            <ArrowRight className="w-3.5 h-3.5" />
          </button>
        </div>
      </div>
    </div>
  );
};

export default MemberCard;

import React, { useState, useEffect, useRef } from 'react';
import { Church as ChurchIcon, Save, MapPin, Phone, Mail, Camera, Search, Loader2, Trash2, ChevronDown } from 'lucide-react';
import { Church, SystemUser } from '../types';
import { KoinoniaDB } from '../services/db';

interface ChurchModuleProps {
  churchId: string;
}

const ChurchModule: React.FC<ChurchModuleProps> = ({ churchId }) => {
  const [church, setChurch] = useState<Church | null>(null);
  const [team, setTeam] = useState<SystemUser[]>([]);
  const [isEditing, setIsEditing] = useState(false);
  const [isLoadingCep, setIsLoadingCep] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const initializeData = () => {
      // Carregar dados da igreja
      const churches = KoinoniaDB.getAllChurches();
      let found = churches.find(c => c.id === churchId);

      if (!found && churchId !== 'default') {
        found = churches[0];
      }

      if (found) {
        setChurch(found);
      } else {
        const defaultChurch: Church = {
          id: churchId || 'default',
          name: 'Minha Igreja Koinonia',
          pastor_name: 'Pastor Responsável',
          cep: '',
          address: 'Endereço da Igreja, 123',
          city: '',
          state: '',
          phone: '(00) 00000-0000',
          email: 'contato@igreja.com',
          created_at: new Date()
        };
        setChurch(defaultChurch);
        if (churches.length === 0) {
          KoinoniaDB.saveChurches([defaultChurch]);
        }
      }

      // Carregar membros da equipe para o seletor de pastor
      setTeam(KoinoniaDB.getAllUsers());
    };

    initializeData();
  }, [churchId]);

  const handleCepLookup = async (cep: string) => {
    const cleanCep = cep.replace(/\D/g, '');
    if (cleanCep.length === 8) {
      setIsLoadingCep(true);
      try {
        const response = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`);
        const data = await response.json();

        if (!data.erro && church) {
          setChurch({
            ...church,
            cep: cleanCep,
            address: `${data.logradouro}${data.bairro ? ', ' + data.bairro : ''}`,
            city: data.localidade,
            state: data.uf
          });
        }
      } catch (error) {
        console.error("Erro ao buscar CEP:", error);
      } finally {
        setIsLoadingCep(false);
      }
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && church) {
      if (file.size > 2 * 1024 * 1024) {
        alert("A imagem deve ter no máximo 2MB");
        return;
      }

      const reader = new FileReader();
      reader.onloadend = () => {
        setChurch({
          ...church,
          logo_url: reader.result as string
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const removeLogo = () => {
    if (church) {
      setChurch({ ...church, logo_url: undefined });
    }
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!church) return;

    const churches = KoinoniaDB.getAllChurches();
    const index = churches.findIndex(c => c.id === church.id);

    let updatedChurches;
    if (index !== -1) {
      updatedChurches = [...churches];
      updatedChurches[index] = church;
    } else {
      updatedChurches = [...churches, church];
    }

    KoinoniaDB.saveChurches(updatedChurches);
    setIsEditing(false);
    alert('Os dados da sua igreja foram atualizados com sucesso!');
  };

  if (!church) {
    return (
      <div className="h-full flex items-center justify-center text-slate-400 font-bold uppercase tracking-widest p-8 text-center">
        Carregando dados da instituição...
      </div>
    );
  }

  return (
    <div className="p-8 space-y-8 overflow-y-auto h-full max-w-5xl mx-auto">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tighter uppercase">Minha Igreja</h2>
