import React, { useState } from 'react';
import { Member, MemberStage, ScheduleEvent } from '../types';
import { STAGES } from '../constants';
import { generateHumanizedMessage } from '../services/geminiService';
import { MessageCircle, ArrowRight, Loader2, MapPin, History, ChevronRight, Phone } from 'lucide-react';

interface MemberCardProps {
  member: Member;
  events?: ScheduleEvent[];
  onMove?: (id: string, newStage: MemberStage) => void;
  onClick?: (member: Member) => void;
  onEditEvent?: (event: ScheduleEvent) => void;
}

const MemberCard: React.FC<MemberCardProps> = ({ member, events = [], onMove, onClick, onEditEvent }) => {
  const [isGenerating, setIsGenerating] = useState(false);

  const getScoreColor = (score: number) => {
    if (score > 80) return 'bg-emerald-500';
    if (score > 50) return 'bg-amber-500';
    return 'bg-rose-500';
  };

  const handleNextStage = (e: React.MouseEvent) => {
    e.stopPropagation();
    const currentIndex = STAGES.findIndex(s => s.id === member.stage);
    if (currentIndex < STAGES.length - 1 && onMove) {
      onMove(member.id, STAGES[currentIndex + 1].id as MemberStage);
    }
  };

  const handleGenerateMessage = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (isGenerating) return;
    setIsGenerating(true);
    const stageLabel = STAGES.find(s => s.id === member.stage)?.label || member.stage;
    try {
      const msg = await generateHumanizedMessage(
        member.name, 
        stageLabel, 
        "Contato caloroso de acompanhamento da liderança"
      );
      alert(`Mensagem Gerada para ${member.name}:\n\n${msg}`);
    } catch (err) {
      console.error(err);
    } finally {
      setIsGenerating(false);
    }
  };

  const memberEvents = events
    .filter(e => e.member_id === member.id)
    .sort((a, b) => b.start_date.getTime() - a.start_date.getTime())
    .slice(0, 1); // Reduzido para apenas 1 evento para manter o card compacto

  const isAtLastStage = STAGES.findIndex(s => s.id === member.stage) === STAGES.length - 1;

  return (
    <div 
      onClick={() => onClick?.(member)}
      className="bg-white p-3.5 rounded-xl shadow-sm border border-slate-100 hover:shadow-md transition-all group cursor-pointer active:scale-[0.98] flex flex-col gap-3 relative overflow-hidden"
    >
      <div className={`absolute left-0 top-0 bottom-0 w-1 ${getScoreColor(member.engagement_score)}`} />

      <div className="flex justify-between items-start gap-2">
        <div className="flex-1 min-w-0">
          <h4 className="font-black text-slate-800 text-xs truncate leading-tight uppercase tracking-tight">{member.name}</h4>
          <p className="text-[9px] font-bold text-indigo-500 uppercase tracking-tighter mt-0.5">
            {member.religion || 'Religião não inf.'}
          </p>
        </div>
        <div className="flex shrink-0">
          {member.channel === 'INSTAGRAM' && (
            <div className="w-4 h-4 rounded-full bg-pink-500 flex items-center justify-center text-white border border-white" title="Instagram">
              <span className="text-[7px] font-black">IG</span>
            </div>
          )}
          {member.channel === 'QR_CODE' && (
            <div className="w-4 h-4 rounded-full bg-blue-500 flex items-center justify-center text-white border border-white" title="QR Code">
              <span className="text-[7px] font-black">QR</span>
            </div>
          )}
        </div>
      </div>

      <div className="space-y-1">
        <div className="flex items-center gap-1.5 text-[10px] text-slate-500 font-medium">
          <Phone className="w-3 h-3 text-slate-300" />
          <span className="truncate">{member.phone || 'Sem fone'}</span>
        </div>
        <div className="flex items-start gap-1.5 text-[10px] text-slate-500 font-medium">
          <MapPin className="w-3 h-3 text-slate-300 shrink-0" />
          <span className="line-clamp-1">{member.address || 'Sem endereço'}</span>
        </div>
      </div>

      {memberEvents.length > 0 && (
        <div className="bg-slate-50 p-2 rounded-lg">
          {memberEvents.map(event => (
            <button 
              key={event.id}
              onClick={(e) => { e.stopPropagation(); onEditEvent?.(event); }}
              className="w-full flex items-center justify-between text-left group/ev"
            >
              <div className="flex items-center gap-1.5 min-w-0">
                <History className="w-2.5 h-2.5 text-slate-300" />
                <span className="text-[9px] font-bold text-slate-600 truncate">{event.title}</span>
              </div>
              <ChevronRight className="w-2.5 h-2.5 text-slate-300 group-hover/ev:text-indigo-500" />
            </button>
          ))}
        </div>
      )}

      <div className="flex items-center justify-between pt-1 mt-auto">
        <div className="flex flex-col">
          <div className="flex items-center gap-1">
             <div className="w-1.5 h-1.5 rounded-full bg-indigo-500 animate-pulse" />
             <p className="text-[10px] font-black text-slate-800">{member.engagement_score}% <span className="text-slate-400 font-bold ml-1 tracking-widest uppercase text-[8px]">Score</span></p>
          </div>
        </div>

        <div className="flex gap-1">
          <button 
            onClick={handleGenerateMessage}
            disabled={isGenerating}
            className="w-7 h-7 rounded-lg bg-emerald-50 text-emerald-600 hover:bg-emerald-600 hover:text-white disabled:opacity-50 transition-all flex items-center justify-center"
            title="IA"
          >
            {isGenerating ? <Loader2 className="w-3 h-3 animate-spin" /> : <MessageCircle className="w-3 h-3" />}
          </button>
          <button 
            onClick={handleNextStage}
            disabled={isAtLastStage}
            className="w-7 h-7 rounded-lg bg-slate-50 text-slate-600 hover:bg-indigo-600 hover:text-white disabled:opacity-30 transition-all flex items-center justify-center"
          >
            <ArrowRight className="w-3 h-3" />
          </button>
        </div>
      </div>
    </div>
  );
};

export default MemberCard;

import React, { useState } from 'react';
import { 
  Calendar as CalendarIcon, 
  Clock, 
  MapPin, 
  Plus, 
  ChevronLeft, 
  ChevronRight, 
  CalendarDays,
  User as UserIcon,
  Edit3
} from 'lucide-react';
import { ScheduleEvent, EventType, SystemUser } from '../types';

interface ScheduleModuleProps {
  events: ScheduleEvent[];
  team?: SystemUser[];
  onAddEvent?: (date?: Date) => void;
  onEditEvent?: (event: ScheduleEvent) => void;
}

const ScheduleModule: React.FC<ScheduleModuleProps> = ({ events, team = [], onAddEvent, onEditEvent }) => {
  const [viewDate, setViewDate] = useState(new Date());

  const getEventTypeStyle = (type: EventType) => {
    switch (type) {
      case EventType.SERVICE: return 'bg-indigo-100 text-indigo-700 border-indigo-200';
      case EventType.MEETING: return 'bg-amber-100 text-amber-700 border-amber-200';
      case EventType.EVENT: return 'bg-purple-100 text-purple-700 border-purple-200';
      case EventType.FOLLOW_UP: return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case EventType.VISIT: return 'bg-rose-100 text-rose-700 border-rose-200';
      default: return 'bg-slate-100 text-slate-700 border-slate-200';
    }
  };

  const getEventTypeLabel = (type: EventType) => {
    switch (type) {
      case EventType.SERVICE: return 'Culto';
      case EventType.MEETING: return 'Reunião';
      case EventType.EVENT: return 'Evento';
      case EventType.FOLLOW_UP: return 'Acomp.';
      case EventType.VISIT: return 'Visita';
      default: return 'Geral';
    }
  };

  const getResponsibleName = (id?: string) => {
    if (!id) return null;
    return team.find(t => t.id === id)?.name || 'N/D';
  };

  const nextMonth = () => {
    setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() + 1, 1));
  };

  const prevMonth = () => {
    setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() - 1, 1));
  };

  const monthName = viewDate.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' });

  const daysInMonth = new Date(viewDate.getFullYear(), viewDate.getMonth() + 1, 0).getDate();
  const firstDayOfMonth = new Date(viewDate.getFullYear(), viewDate.getMonth(), 1).getDay();
  const calendarDays = Array.from({ length: 42 }, (_, i) => {
    const day = i - firstDayOfMonth + 1;
    return day > 0 && day <= daysInMonth ? day : null;
  });

  const isToday = (day: number | null) => {
    if (!day) return false;
    const now = new Date();
    return now.getDate() === day && now.getMonth() === viewDate.getMonth() && now.getFullYear() === viewDate.getFullYear();
  };

  const hasEventOnDay = (day: number | null) => {
    if (!day) return false;
    return events.some(e => {
      const d = new Date(e.start_date);
      return d.getDate() === day && d.getMonth() === viewDate.getMonth() && d.getFullYear() === viewDate.getFullYear();
    });
  };

  return (
    <div className="p-6 h-full overflow-hidden flex flex-col gap-6 bg-slate-50/50">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tighter uppercase">Agenda</h2>
          <p className="text-sm text-slate-500 font-medium">Controle de compromissos da comunidade.</p>
        </div>
        <button 
          onClick={() => onAddEvent?.()}
          className="flex items-center gap-2 px-4 py-2.5 bg-indigo-600 text-white rounded-xl font-black shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95 text-[10px] uppercase tracking-widest"
        >
          <Plus className="w-4 h-4" /> Novo Evento
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 flex-1 overflow-hidden">
        <div className="lg:col-span-4 flex flex-col gap-6 overflow-y-auto">
          <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm">
            <div className="flex justify-between items-center mb-4">
              <h3 className="font-black text-slate-800 uppercase text-[10px] tracking-widest capitalize">{monthName}</h3>
              <div className="flex gap-1">
                <button onClick={prevMonth} className="p-1 hover:bg-slate-50 rounded-lg text-slate-400"><ChevronLeft className="w-4 h-4" /></button>
                <button onClick={nextMonth} className="p-1 hover:bg-slate-50 rounded-lg text-slate-400"><ChevronRight className="w-4 h-4" /></button>
              </div>
            </div>
            <div className="grid grid-cols-7 gap-1 text-center mb-1">
              {['D','S','T','Q','Q','S','S'].map(d => <span key={d} className="text-[9px] font-black text-slate-300">{d}</span>)}
            </div>
            <div className="grid grid-cols-7 gap-1 text-center">
              {calendarDays.map((day, i) => (
                <button 
                  key={i} 
                  disabled={!day}
                  onClick={() => day && onAddEvent?.(new Date(viewDate.getFullYear(), viewDate.getMonth(), day))}
                  className={`aspect-square flex flex-col items-center justify-center text-[11px] font-black rounded-lg transition-all relative ${day ? 'hover:bg-indigo-50 text-slate-500 cursor-pointer' : 'opacity-0'} ${isToday(day) ? 'bg-indigo-600 text-white shadow-md' : ''}`}
                >
                  {day}
                  {hasEventOnDay(day) && (
                    <span className={`absolute bottom-1 w-1 h-1 rounded-full ${isToday(day) ? 'bg-white' : 'bg-indigo-400'}`}></span>
                  )}
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="lg:col-span-8 bg-white rounded-3xl border border-slate-100 shadow-sm flex flex-col overflow-hidden">
          <div className="px-6 py-4 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
            <div className="flex items-center gap-2">
              <CalendarDays className="w-4 h-4 text-indigo-600" />
              <h3 className="text-sm font-black text-slate-800 uppercase tracking-tight">Compromissos</h3>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-2">
            {events.filter(e => e.start_date.getMonth() === viewDate.getMonth() && e.start_date.getFullYear() === viewDate.getFullYear()).length > 0 ? 
              events
                .filter(e => e.start_date.getMonth() === viewDate.getMonth() && e.start_date.getFullYear() === viewDate.getFullYear())
                .sort((a,b) => a.start_date.getTime() - b.start_date.getTime())
                .map(event => (
              <div 
                key={event.id} 
                onClick={() => onEditEvent?.(event)}
                className="group p-3 bg-slate-50/50 hover:bg-white border border-transparent hover:border-indigo-100 rounded-xl transition-all cursor-pointer flex items-center justify-between gap-4"
              >
                <div className="flex items-center gap-4 flex-1 min-w-0">
                  <div className="flex flex-col items-center justify-center bg-white border border-slate-100 rounded-lg w-12 h-12 shadow-sm shrink-0">
                    <span className="text-[8px] font-black text-slate-400 uppercase leading-none">{event.start_date.toLocaleDateString('pt-BR', {month: 'short'})}</span>
                    <span className="text-base font-black text-slate-800 leading-none mt-0.5">{event.start_date.getDate()}</span>
                  </div>

                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <span className={`px-1.5 py-0.5 rounded text-[8px] font-black uppercase border ${getEventTypeStyle(event.type)}`}>
                        {getEventTypeLabel(event.type)}
                      </span>
                      <h4 className="font-bold text-slate-800 text-sm truncate">{event.title}</h4>
                    </div>
                    <div className="flex items-center gap-3 mt-1 overflow-hidden">
                      <div className="flex items-center gap-1 text-[10px] text-slate-400 font-bold shrink-0">
                        <Clock className="w-3 h-3" />
                        {event.start_date.toLocaleTimeString('pt-BR', {hour: '2-digit', minute: '2-digit'})}
                      </div>
                      <div className="flex items-center gap-1 text-[10px] text-slate-400 font-bold truncate">
                        <MapPin className="w-3 h-3 shrink-0" />
                        {event.location}
                      </div>
                    </div>
                  </div>
                </div>

                <div className="flex items-center gap-2 shrink-0">
                  {event.responsible_id && (
                    <div className="hidden md:flex items-center gap-1 px-2 py-1 bg-indigo-50 text-indigo-600 rounded-lg text-[9px] font-black uppercase">
                      <UserIcon className="w-3 h-3" />
                      {getResponsibleName(event.responsible_id)}
                    </div>
                  )}
                  <button className="p-2 text-slate-300 group-hover:text-indigo-600 transition-all">
                    <Edit3 className="w-4 h-4" />
                  </button>
                </div>
              </div>
            )) : (
              <div className="py-20 flex flex-col items-center justify-center text-slate-300 gap-3 opacity-50">
                <CalendarIcon className="w-10 h-10" />
                <p className="font-black text-[10px] uppercase tracking-widest text-center">Nenhum evento agendado</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

