        engagement_score: 50,
        church_id: currentUser?.church_id || 'default'
      } as Member;
      updated = [...members, newMember];
    }
    setMembers(updated);
    KoinoniaDB.saveMembers(updated);
    setIsMemberModalOpen(false);
    setSelectedMember(null);
  };

  const handleDeleteMember = (id: string) => {
    if (window.confirm('Excluir este contato permanentemente?')) {
      const updated = members.filter(m => m.id !== id);
      setMembers(updated);
      KoinoniaDB.saveMembers(updated);
    }
  };

  const handleSaveEvent = (eventData: Partial<ScheduleEvent>) => {
    let updated;
    if (eventData.id) {
      updated = events.map(e => e.id === eventData.id ? { ...e, ...eventData } as ScheduleEvent : e);
    } else {
      const newEvent: ScheduleEvent = {
        ...eventData,
        id: Math.random().toString(36).substr(2, 9),
        created_at: new Date(),
        church_id: currentUser?.church_id || 'default'
      } as ScheduleEvent;
      updated = [...events, newEvent];
    }
    setEvents(updated);
    KoinoniaDB.saveEvents(updated);
    setIsEventModalOpen(false);
    setSelectedEvent(null);
  };

  const handleQuickAddTask = (member: Member) => {
    setSelectedEvent({
      id: '',
      title: `Tarefa: Acompanhar ${member.name}`,
      description: `Tarefa gerada automaticamente para acompanhamento de jornada.`,
      type: EventType.FOLLOW_UP,
      start_date: new Date(),
      end_date: new Date(new Date().getTime() + 30 * 60 * 1000),
      member_id: member.id,
      responsible_id: member.responsible_leader_id || currentUser?.id,
      church_id: currentUser?.church_id || 'default',
      created_at: new Date()
    } as ScheduleEvent);
    setIsEventModalOpen(true);
  };

  const moveMember = (id: string, nextStage: MemberStage) => {
    const updated = members.map(m => m.id === id ? { ...m, stage: nextStage, last_activity: new Date() } : m);
    setMembers(updated);
    KoinoniaDB.saveMembers(updated);
  };

  if (!isLoggedIn) {
    return <LoginScreen onLogin={handleLoginSuccess} />;
  }

  return (
    <div className="flex h-screen bg-white overflow-hidden font-inter">
      <aside className={`${isSidebarOpen ? 'w-80' : 'w-24'} bg-slate-900 transition-all duration-500 flex flex-col z-50 shadow-2xl relative`}>
        <div className="p-10 flex items-center gap-5">
          <div className="w-12 h-12 bg-indigo-500 rounded-[18px] flex items-center justify-center shrink-0 shadow-lg shadow-indigo-500/30">
            <Shield className="w-6 h-6 text-white" />
          </div>
          {isSidebarOpen && <span className="font-black text-2xl text-white tracking-tight uppercase">Koinonia</span>}
        </div>

        <nav className="flex-1 px-8 py-6 space-y-2 overflow-y-auto scrollbar-hide">
          {navItems.map(item => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-5 px-5 py-4 rounded-[24px] transition-all group ${
                activeTab === item.id 
                  ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/30' 
                  : 'text-slate-500 hover:bg-slate-800 hover:text-white'
              }`}
            >
              <div className={`${activeTab === item.id ? 'text-white' : 'text-slate-500 group-hover:text-indigo-400'} transition-colors`}>
                {item.icon}
              </div>
              {isSidebarOpen && <span className="font-black text-[10px] uppercase tracking-[0.15em]">{item.label}</span>}
            </button>
          ))}
        </nav>

        <div className="p-8 border-t border-slate-800">
           <button onClick={handleLogout} className="w-full flex items-center gap-5 px-5 py-4 rounded-[24px] text-rose-400 hover:bg-rose-500/10 transition-all group">
             <LogOut className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
             {isSidebarOpen && <span className="font-black text-[10px] uppercase tracking-[0.15em]">Sair do Sistema</span>}
           </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-slate-50 overflow-hidden">
        <header className="h-24 bg-white border-b border-slate-100 flex items-center justify-between px-12 shrink-0 z-40">
          <div className="flex items-center gap-8">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-3 hover:bg-slate-50 rounded-2xl text-slate-400 transition-all">
              {isSidebarOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
            <div>
              <h2 className="text-2xl font-black text-slate-800 tracking-tighter uppercase">
                {navItems.find(i => i.id === activeTab)?.label}
              </h2>
            </div>
          </div>

          <div className="flex items-center gap-8">
            <div className="relative group hidden sm:block">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
              <input 
                type="text" 
                placeholder="Pesquisa rápida..." 
                className="pl-12 pr-6 py-3 bg-slate-50 border-none rounded-2xl w-64 text-sm font-medium text-slate-700 focus:ring-2 focus:ring-indigo-500 transition-all" 
              />
            </div>

            <div className="relative">
              <button 
