        <div className="flex gap-2">
          <select 
            className="px-6 py-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 font-bold text-xs uppercase tracking-widest text-slate-600 outline-none appearance-none"
