                  <td className="px-6 py-4">
                    {getStageBadge(member.stage)}
                    <p className="text-[9px] text-slate-400 uppercase font-black mt-1 ml-1">{member.channel}</p>
                  </td>
                  <td className="px-6 py-4">
                    {member.interests ? (
                      <span className="px-2 py-1 bg-indigo-50 text-indigo-500 rounded-lg text-[10px] font-bold italic">
