        >
          <UserPlus className="w-5 h-5" /> Adicionar Novo
        </button>
      </div>

      {/* Mini Stats from Image Context */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {STAGES.map(stage => (
          <div key={stage.id} className="bg-white p-6 rounded-[28px] border border-slate-100 shadow-sm flex items-center gap-4">
            <div className={`p-3 rounded-2xl ${stage.color}`}>
              {stage.icon}
            </div>
            <div>
              <p className="text-2xl font-black text-slate-800 leading-none">
                {members.filter(m => m.stage === stage.id).length}
              </p>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">{stage.label}s</p>
            </div>
          </div>
        ))}
