      </div>
    </div>
  );
};

export default ContactsModule;

import React, { useState } from 'react';
import { Member, MemberStage, ScheduleEvent, SystemUser } from '../types';
import { STAGES } from '../constants';
import { generateHumanizedMessage } from '../services/geminiService';
import { MessageCircle, ArrowRight, Loader2, History, ChevronRight, Phone, UserCheck, CalendarPlus, Mail } from 'lucide-react';

interface MemberCardProps {
  member: Member;
  events?: ScheduleEvent[];
  team?: SystemUser[];
  onMove?: (id: string, newStage: MemberStage) => void;
  onClick?: (member: Member) => void;
  onEditEvent?: (event: ScheduleEvent) => void;
  onAddTask?: (member: Member) => void;
}

const MemberCard: React.FC<MemberCardProps> = ({ 
  member, 
  events = [], 
  team = [], 
  onMove, 
  onClick, 
  onEditEvent,
  onAddTask
}) => {
  const [isGenerating, setIsGenerating] = useState(false);

  const getScoreColor = (score: number) => {
    if (score > 80) return 'bg-emerald-500';
    if (score > 50) return 'bg-amber-500';
    return 'bg-rose-500';
  };

  const leaderName = team.find(u => u.id === member.responsible_leader_id)?.name || 'Sem Líder';

  const handleNextStage = (e: React.MouseEvent) => {
    e.stopPropagation();
    const currentIndex = STAGES.findIndex(s => s.id === member.stage);
    if (currentIndex < STAGES.length - 1 && onMove) {
      onMove(member.id, STAGES[currentIndex + 1].id as MemberStage);
    }
  };

  const handleGenerateMessage = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (isGenerating) return;
    setIsGenerating(true);
    const stageLabel = STAGES.find(s => s.id === member.stage)?.label || member.stage;
    try {
      const msg = await generateHumanizedMessage(
        member.name, 
        stageLabel, 
        "Contato caloroso de acompanhamento da liderança"
      );
      alert(`Mensagem Gerada:\n\n${msg}`);
    } catch (err) {
      console.error(err);
    } finally {
      setIsGenerating(false);
    }
  };

  const memberEvents = events
    .filter(e => e.member_id === member.id)
    .sort((a, b) => b.start_date.getTime() - a.start_date.getTime())
    .slice(0, 1);

  const isAtLastStage = STAGES.findIndex(s => s.id === member.stage) === STAGES.length - 1;

  return (
    <div 
      onClick={() => onClick?.(member)}
      className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-all group cursor-pointer active:scale-[0.98] flex flex-col gap-3 relative overflow-hidden"
    >
      <div className={`absolute left-0 top-0 bottom-0 w-1 ${getScoreColor(member.engagement_score)}`} />

      <div className="flex justify-between items-start gap-2">
        <div className="flex-1 min-w-0">
          <h4 className="font-black text-slate-800 text-sm leading-tight">{member.name}</h4>
          <div className="flex items-center gap-1 mt-1">
            <History className="w-3 h-3 text-slate-300" />
            <p className="text-[10px] font-bold text-slate-400">
              {member.registration_date.toLocaleDateString('pt-BR')}
            </p>
          </div>
        </div>
      </div>

      <div className="space-y-1 mt-1">
        <div className="flex items-center gap-1.5 text-[10px] text-slate-500 font-medium">
          <Phone className="w-3 h-3 text-slate-300" />
          <span className="truncate">{member.phone || 'N/A'}</span>
        </div>
        <div className="flex items-center gap-1.5 text-[10px] text-slate-500 font-medium">
          <UserCheck className="w-3 h-3 text-slate-300" />
          <span className="truncate">{leaderName}</span>
        </div>
      </div>

      <div className="flex items-center justify-between pt-2 border-t border-slate-50 mt-1">
        <div className="flex gap-1.5">
          <button 
            onClick={(e) => { e.stopPropagation(); onAddTask?.(member); }}
            className="w-7 h-7 rounded-lg bg-indigo-50 text-indigo-600 hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center shadow-sm"
            title="Agendar"
          >
            <CalendarPlus className="w-3.5 h-3.5" />
          </button>
          <a 
            href={`mailto:${member.email}`}
            onClick={(e) => e.stopPropagation()}
            className="w-7 h-7 rounded-lg bg-blue-50 text-blue-600 hover:bg-blue-600 hover:text-white transition-all flex items-center justify-center shadow-sm"
            title="E-mail"
          >
            <Mail className="w-3.5 h-3.5" />
          </a>
          <button 
            onClick={handleGenerateMessage}
            disabled={isGenerating}
            className="w-7 h-7 rounded-lg bg-emerald-50 text-emerald-600 hover:bg-emerald-600 hover:text-white disabled:opacity-50 transition-all flex items-center justify-center shadow-sm"
            title="Sugerir Mensagem"
          >
            {isGenerating ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <MessageCircle className="w-3.5 h-3.5" />}
          </button>
        </div>

        <button 
          onClick={handleNextStage}
          disabled={isAtLastStage}
          className="w-7 h-7 rounded-lg bg-slate-50 text-slate-600 hover:bg-indigo-600 hover:text-white disabled:opacity-30 transition-all flex items-center justify-center shadow-sm"
          title="Mover"
        >
          <ArrowRight className="w-3.5 h-3.5" />
        </button>
      </div>
    </div>
  );
};

export default MemberCard;

import React, { useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell
} from 'recharts';
import { TrendingUp, Users, Target, Activity, AlertTriangle } from 'lucide-react';
import { Member, MemberStage } from '../types';
import { STAGES } from '../constants';

interface AnalyticsDashboardProps {
  members: Member[];
}

const AnalyticsDashboard: React.FC<AnalyticsDashboardProps> = ({ members }) => {
  const COLORS = ['#3b82f6', '#f59e0b', '#a855f7', '#10b981'];

  const stageData = useMemo(() => [
    { name: 'Novos', value: members.filter(m => m.stage === MemberStage.NEW).length },
    { name: '1º Contato', value: members.filter(m => m.stage === MemberStage.FIRST_CONTACT).length },
    { name: 'Retornando', value: members.filter(m => m.stage === MemberStage.RETURNING).length },
    { name: 'Membros', value: members.filter(m => m.stage === MemberStage.MEMBER).length },
  ], [members]);

  const growthData = useMemo(() => [
    { day: 'Seg', count: Math.floor(members.length * 0.1) },
    { day: 'Ter', count: Math.floor(members.length * 0.15) },
    { day: 'Qua', count: Math.floor(members.length * 0.12) },
    { day: 'Qui', count: Math.floor(members.length * 0.2) },
    { day: 'Sex', count: Math.floor(members.length * 0.18) },
    { day: 'Sáb', count: Math.floor(members.length * 0.25) },
    { day: 'Dom', count: Math.floor(members.length * 0.35) },
  ], [members]);

  const activeRate = useMemo(() => {
    const active = members.filter(m => m.stage === MemberStage.MEMBER).length;
    return members.length > 0 ? Math.round((active / members.length) * 100) : 0;
  }, [members]);

  const avgEngagement = useMemo(() => {
    if (members.length === 0) return 0;
    return Math.round(members.reduce((acc, m) => acc + (m.engagement_score || 0), 0) / members.length);
  }, [members]);

  return (
    <div className="p-8 space-y-8 overflow-y-auto h-full bg-slate-50/50">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {[
          { label: 'Total no Sistema', value: members.length, icon: <Users />, color: 'text-indigo-600', bg: 'bg-indigo-50' },
          { label: 'Efetivação Membro', value: `${activeRate}%`, icon: <Activity />, color: 'text-emerald-600', bg: 'bg-emerald-50' },
          { label: 'Score Médio', value: `${avgEngagement}%`, icon: <Target />, color: 'text-blue-600', bg: 'bg-blue-50' },
          { label: 'Atenção Necessária', value: members.filter(m => m.engagement_score < 30).length, icon: <AlertTriangle />, color: 'text-amber-600', bg: 'bg-amber-50' },
        ].map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-[32px] shadow-sm border border-slate-100 flex items-center justify-between transition-all hover:shadow-md">
            <div>
              <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">{stat.label}</p>
              <h3 className="text-3xl font-black text-slate-800 mt-1">{stat.value}</h3>
            </div>
            <div className={`p-4 rounded-2xl ${stat.bg} ${stat.color}`}>
              {React.cloneElement(stat.icon as React.ReactElement, { className: 'w-7 h-7' })}
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-8 rounded-[40px] shadow-sm border border-slate-100">
          <div className="flex justify-between items-center mb-8">
            <div>
               <h3 className="text-xl font-black text-slate-800">Crescimento Semanal</h3>
               <p className="text-xs text-slate-400 font-medium">Novos registros processados por dia</p>
            </div>
          </div>
          <div className="h-72">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={growthData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 'bold'}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 25px rgba(0,0,0,0.05)', padding: '12px'}}
                />
                <Bar dataKey="count" fill="#6366f1" radius={[8, 8, 0, 0]} barSize={40} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[40px] shadow-sm border border-slate-100 flex flex-col">
          <h3 className="text-xl font-black text-slate-800 mb-2">Estágio da Jornada</h3>
          <p className="text-xs text-slate-400 font-medium mb-8">Distribuição atual por categoria</p>
          <div className="flex-1 min-h-[250px]">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={stageData}
                  cx="50%"
                  cy="50%"
                  innerRadius={70}
                  outerRadius={100}
                  paddingAngle={8}
                  dataKey="value"
                >
                  {stageData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-6 grid grid-cols-2 gap-3 pt-6 border-t border-slate-50">
            {stageData.map((s, i) => (
              <div key={i} className="flex items-center gap-2">
                <div className="w-2.5 h-2.5 rounded-full" style={{backgroundColor: COLORS[i]}} />
                <span className="text-[10px] text-slate-500 font-bold uppercase truncate">{s.name}: {s.value}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AnalyticsDashboard;

