  const [activeTab, setActiveTab] = useState<string>('analytics');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [currentUser, setCurrentUser] = useState<SystemUser | null>(null);
  const [members, setMembers] = useState<Member[]>([]);
  const [events, setEvents] = useState<ScheduleEvent[]>([]);
  const [team, setTeam] = useState<SystemUser[]>([]);

  // Modals state
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [isEventModalOpen, setIsEventModalOpen] = useState(false);
  const [selectedMember, setSelectedMember] = useState<Member | null>(null);
  const [selectedEvent, setSelectedEvent] = useState<ScheduleEvent | null>(null);

  useEffect(() => {
    setMembers(KoinoniaDB.getAllMembers());
    setEvents(KoinoniaDB.getAllEvents());
    setTeam(KoinoniaDB.getAllUsers());

    const savedUser = localStorage.getItem('koinonia_session');
    if (savedUser) {
      setCurrentUser(JSON.parse(savedUser));
      setIsLoggedIn(true);
    }
  }, [activeTab]);

  const handleLoginSuccess = (user: SystemUser) => {
    setCurrentUser(user);
    localStorage.setItem('koinonia_session', JSON.stringify(user));
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    localStorage.removeItem('koinonia_session');
    setIsLoggedIn(false);
    setCurrentUser(null);
  };

  const handleSaveMember = (memberData: Partial<Member>) => {
    let updated;
    if (memberData.id) {
      updated = members.map(m => m.id === memberData.id ? { ...m, ...memberData } as Member : m);
    } else {
      const newMember: Member = {
        ...memberData,
        id: Math.random().toString(36).substr(2, 9),
        registration_date: new Date(),
        last_activity: new Date(),
        engagement_score: 50,
        church_id: currentUser?.church_id || 'default'
      } as Member;
      updated = [...members, newMember];
    }
    setMembers(updated);
    KoinoniaDB.saveMembers(updated);
    setIsMemberModalOpen(false);
    setSelectedMember(null);
  };

  const handleImportMembers = (newMembers: Member[]) => {
    const updated = [...members, ...newMembers];
    setMembers(updated);
    KoinoniaDB.saveMembers(updated);
    alert(`${newMembers.length} contatos importados com sucesso!`);
  };

  const handleDeleteMember = (id: string) => {
    if (window.confirm('Excluir este contato permanentemente?')) {
      const updated = members.filter(m => m.id !== id);
      setMembers(updated);
      KoinoniaDB.saveMembers(updated);
    }
  };

  const handleSaveEvent = (eventData: Partial<ScheduleEvent>) => {
    let updated;
    if (eventData.id) {
      updated = events.map(e => e.id === eventData.id ? { ...e, ...eventData } as ScheduleEvent : e);
    } else {
      const newEvent: ScheduleEvent = {
        ...eventData,
        id: Math.random().toString(36).substr(2, 9),
        created_at: new Date(),
        church_id: currentUser?.church_id || 'default'
      } as ScheduleEvent;
      updated = [...events, newEvent];
    }
    setEvents(updated);
    KoinoniaDB.saveEvents(updated);
    setIsEventModalOpen(false);
    setSelectedEvent(null);
  };

  const handleDeleteEvent = (id: string) => {
    if (window.confirm('Deseja excluir este agendamento definitivamente?')) {
      const updated = events.filter(e => e.id !== id);
      setEvents(updated);
      KoinoniaDB.saveEvents(updated);
    }
  };

  const handleQuickAddTask = (member: Member) => {
    setSelectedEvent({
      id: '',
      title: `Acompanhamento: ${member.name}`,
      description: `Acompanhamento de jornada agendado via módulo de contatos.`,
      type: EventType.FOLLOW_UP,
      start_date: new Date(),
      end_date: new Date(new Date().getTime() + 60 * 60 * 1000),
      member_id: member.id,
      responsible_id: member.responsible_leader_id || currentUser?.id,
      church_id: currentUser?.church_id || 'default',
      created_at: new Date()
    } as ScheduleEvent);
    setIsEventModalOpen(true);
  };

  const moveMember = (id: string, nextStage: MemberStage) => {
    const updated = members.map(m => m.id === id ? { ...m, stage: nextStage, last_activity: new Date() } : m);
    setMembers(updated);
    KoinoniaDB.saveMembers(updated);
  };

  if (!isLoggedIn) {
    return <LoginScreen onLogin={handleLoginSuccess} />;
  }

  return (
    <div className="flex h-screen bg-white overflow-hidden font-inter">
      <aside className={`${isSidebarOpen ? 'w-80' : 'w-24'} bg-slate-900 transition-all duration-500 flex flex-col z-50 shadow-2xl relative`}>
        <div className="p-10 flex items-center gap-5">
          <div className="w-12 h-12 bg-indigo-500 rounded-[18px] flex items-center justify-center shrink-0 shadow-lg shadow-indigo-500/30">
            <Shield className="w-6 h-6 text-white" />
          </div>
          {isSidebarOpen && <span className="font-black text-2xl text-white tracking-tight uppercase">Koinonia</span>}
        </div>

        <nav className="flex-1 px-8 py-6 space-y-2 overflow-y-auto scrollbar-hide">
          {navItems.map(item => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-5 px-5 py-4 rounded-[24px] transition-all group ${
                activeTab === item.id 
                  ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/30' 
                  : 'text-slate-500 hover:bg-slate-800 hover:text-white'
              }`}
            >
              <div className={`${activeTab === item.id ? 'text-white' : 'text-slate-500 group-hover:text-indigo-400'} transition-colors`}>
                {item.icon}
              </div>
              {isSidebarOpen && <span className="font-black text-[10px] uppercase tracking-[0.15em]">{item.label}</span>}
            </button>
          ))}
        </nav>

        <div className="p-8 border-t border-slate-800">
           <button onClick={handleLogout} className="w-full flex items-center gap-5 px-5 py-4 rounded-[24px] text-rose-400 hover:bg-rose-500/10 transition-all group">
             <LogOut className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
             {isSidebarOpen && <span className="font-black text-[10px] uppercase tracking-[0.15em]">Sair</span>}
           </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-slate-50 overflow-hidden">
        <header className="h-24 bg-white border-b border-slate-100 flex items-center justify-between px-12 shrink-0 z-40">
          <div className="flex items-center gap-8">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-3 hover:bg-slate-50 rounded-2xl text-slate-400 transition-all">
              {isSidebarOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
            <div>
              <h2 className="text-2xl font-black text-slate-800 tracking-tighter uppercase">
                {navItems.find(i => i.id === activeTab)?.label}
              </h2>
            </div>
          </div>

          <div className="flex items-center gap-8">
            <div className="relative group hidden sm:block">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
              <input 
                type="text" 
                placeholder="Pesquisa rápida..." 
                className="pl-12 pr-6 py-3 bg-slate-50 border-none rounded-2xl w-64 text-sm font-medium text-slate-700 focus:ring-2 focus:ring-indigo-500 transition-all" 
              />
            </div>

            <div className="relative">
              <button 
                onClick={() => setIsProfileOpen(!isProfileOpen)}
                className="flex items-center gap-4 p-2 pl-5 bg-slate-50 rounded-[28px] border border-slate-100 hover:bg-white hover:shadow-lg hover:shadow-indigo-50 transition-all"
              >
                <div className="text-right">
                  <p className="text-[11px] font-black text-slate-800 leading-none">{currentUser?.name}</p>
                  <p className="text-[8px] font-bold text-indigo-500 uppercase tracking-widest mt-1">{currentUser?.role}</p>
                </div>
                <div className="w-12 h-12 rounded-[20px] bg-indigo-600 flex items-center justify-center text-white font-black shadow-lg shadow-indigo-100">
                  {currentUser?.name?.[0]}
                </div>
              </button>

              {isProfileOpen && (
                <div className="absolute right-0 mt-3 w-64 bg-white rounded-[32px] shadow-2xl border border-slate-100 py-4 z-50 animate-in slide-in-from-top-2 duration-300">
                  <div className="px-6 py-3 border-b border-slate-50 mb-2">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Acesso Logado</p>
                    <p className="text-xs font-bold text-slate-700 mt-1">{currentUser?.email}</p>
                  </div>
                  <button onClick={() => { setActiveTab('settings'); setIsProfileOpen(false); }} className="w-full text-left px-6 py-3 text-xs font-bold text-slate-600 hover:bg-slate-50 hover:text-indigo-600 transition-all">Perfil</button>
                  <button onClick={handleLogout} className="w-full text-left px-6 py-3 text-xs font-bold text-rose-500 hover:bg-rose-50 transition-all">Sair</button>
                </div>
              )}
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-hidden relative">
          {activeTab === 'analytics' && <AnalyticsDashboard members={members} />}
          {activeTab === 'contacts' && (
            <ContactsModule 
              members={members} 
              team={team}
              onEditMember={(m) => { setSelectedMember(m); setIsMemberModalOpen(true); }}
              onDeleteMember={handleDeleteMember}
              onAddMember={() => { setSelectedMember(null); setIsMemberModalOpen(true); }}
              onImportMembers={handleImportMembers}
              onQuickTask={handleQuickAddTask}
            />
          )}
          {activeTab === 'kanban' && (
            <KanbanBoard 
              members={members} 
              events={events}
              team={team}
              onMoveMember={moveMember} 
              onAddMember={() => { setSelectedMember(null); setIsMemberModalOpen(true); }}
              onMemberClick={(m) => { setSelectedMember(m); setIsMemberModalOpen(true); }}
              onEditEvent={(e) => { setSelectedEvent(e); setIsEventModalOpen(true); }}
              onAddTask={handleQuickAddTask}
            />
          )}
          {activeTab === 'agenda' && (
            <ScheduleModule 
              events={events} 
              team={team}
              onAddEvent={() => { setSelectedEvent(null); setIsEventModalOpen(true); }}
              onEditEvent={(e) => { setSelectedEvent(e); setIsEventModalOpen(true); }}
              onDeleteEvent={handleDeleteEvent}
            />
          )}
          {activeTab === 'church' && <ChurchModule churchId={currentUser?.church_id || 'default'} />}
          {activeTab === 'team' && <TeamModule />}
          {activeTab === 'automation' && <AutomationSettings />}
          {activeTab === 'settings' && <SettingsModule />}
        </div>

        <MemberModal 
          isOpen={isMemberModalOpen} 
          onClose={() => setIsMemberModalOpen(false)} 
          onSave={handleSaveMember} 
          initialData={selectedMember} 
          team={team}
          events={events}
          onEditEvent={(e) => { setSelectedEvent(e); setIsEventModalOpen(true); }}
          onDeleteEvent={handleDeleteEvent}
        />
        <EventModal 
          isOpen={isEventModalOpen} 
          onClose={() => setIsEventModalOpen(false)} 
          onSave={handleSaveEvent} 
          initialData={selectedEvent} 
          team={team}
        />
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef } from 'react';
import { 
  Search, 
  UserPlus, 
  Trash2, 
  Edit3,
  Users,
  MessageCircle,
  CalendarPlus,
  UserCheck,
  Mail,
  Upload,
  FileSpreadsheet
} from 'lucide-react';
import { Member, MemberStage, SystemUser } from '../types';
import { STAGES } from '../constants';

interface ContactsModuleProps {
  members: Member[];
  team?: SystemUser[];
  onEditMember: (member: Member) => void;
  onDeleteMember: (id: string) => void;
  onAddMember: () => void;
  onImportMembers?: (members: Member[]) => void;
  onQuickTask?: (member: Member) => void;
}

const ContactsModule: React.FC<ContactsModuleProps> = ({ 
  members, 
  team = [],
  onEditMember, 
  onDeleteMember, 
  onAddMember,
  onImportMembers,
  onQuickTask
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedStage, setSelectedStage] = useState<string>('ALL');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredMembers = useMemo(() => {
    return members.filter(m => {
      const matchesSearch = 
        m.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        m.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (m.phone && m.phone.includes(searchTerm));

      const matchesStage = selectedStage === 'ALL' || m.stage === selectedStage;

      return matchesSearch && matchesStage;
    });
  }, [members, searchTerm, selectedStage]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const text = event.target?.result as string;
        const rows = text.split('\n');
        const newMembers: Member[] = [];

        // Skip header row if exists
        const startIndex = rows[0].toLowerCase().includes('nome') ? 1 : 0;

        for (let i = startIndex; i < rows.length; i++) {
          const columns = rows[i].split(',');
          if (columns.length >= 2 && columns[0].trim()) {
            newMembers.push({
              id: Math.random().toString(36).substr(2, 9),
              name: columns[0].trim(),
              email: columns[1]?.trim() || '',
              phone: columns[2]?.trim() || '',
              gender: columns[3]?.trim() || '',
              stage: MemberStage.NEW,
              channel: columns[4]?.trim() || 'CSV_IMPORT',
              registration_date: new Date(),
              last_activity: new Date(),
              engagement_score: 50,
              church_id: 'default'
            });
          }
        }
        if (newMembers.length > 0 && onImportMembers) {
          onImportMembers(newMembers);
        }
      };
      reader.readAsText(file);
    }
  };

  const getStageBadge = (stageId: MemberStage) => {
    const stage = STAGES.find(s => s.id === stageId);
    return (
      <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase border ${stage?.color} ${stage?.border}`}>
        {stage?.label}
      </span>
    );
  };

  const getLeaderName = (id?: string) => {
    const leader = team.find(u => u.id === id);
    return leader ? leader.name.toUpperCase() : 'SEM RESPONSÁVEL';
  };

  return (
    <div className="p-8 h-full flex flex-col gap-8 bg-slate-50/50 overflow-hidden">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tighter uppercase">Gestão de Contatos</h2>
          <p className="text-slate-500 font-medium">Acompanhe cada pessoa em sua jornada na comunidade.</p>
        </div>
        <div className="flex gap-3">
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileUpload} 
            accept=".csv" 
            className="hidden" 
          />
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center gap-2 px-6 py-4 bg-white text-indigo-600 border border-indigo-100 rounded-2xl font-black shadow-sm hover:bg-indigo-50 transition-all uppercase tracking-widest text-xs"
          >
            <Upload className="w-5 h-5" /> Importar CSV
          </button>
          <button 
            onClick={onAddMember}
            className="flex items-center gap-2 px-6 py-4 bg-indigo-600 text-white rounded-2xl font-black shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95 uppercase tracking-widest text-xs"
          >
            <UserPlus className="w-5 h-5" /> Adicionar Novo
          </button>
        </div>
      </div>

      {/* Mini Stats corrigidos para não pluralizar errado */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {STAGES.map(stage => (
          <div key={stage.id} className="bg-white p-6 rounded-[28px] border border-slate-100 shadow-sm flex items-center gap-4">
            <div className={`p-3 rounded-2xl ${stage.color}`}>
              {stage.icon}
            </div>
            <div>
              <p className="text-2xl font-black text-slate-800 leading-none">
                {members.filter(m => m.stage === stage.id).length}
              </p>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">{stage.label}</p>
            </div>
          </div>
        ))}
      </div>

      <div className="bg-white p-4 rounded-[32px] border border-slate-100 shadow-sm flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-300" />
          <input 
            type="text"
            placeholder="Buscar por nome, email ou telefone..."
            className="w-full pl-12 pr-4 py-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 font-medium text-sm text-slate-700 transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="flex gap-2">
          <select 
            className="px-6 py-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 font-bold text-xs uppercase tracking-widest text-slate-600 outline-none appearance-none"
            value={selectedStage}
            onChange={(e) => setSelectedStage(e.target.value)}
          >
            <option value="ALL">Todos</option>
            {STAGES.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}
          </select>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-[40px] border border-slate-100 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50/50 border-b border-slate-100">
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Pessoa / Gênero</th>
                <th className="px-6 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Estágio & Origem</th>
                <th className="px-6 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Interesses</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredMembers.map((member) => (
                <tr key={member.id} className="group hover:bg-indigo-50/20 transition-all border-b border-slate-50 last:border-0">
                  <td className="px-8 py-5">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-2xl bg-slate-50 border border-slate-100 flex items-center justify-center text-slate-400 font-black group-hover:bg-indigo-600 group-hover:text-white group-hover:border-indigo-600 transition-all shadow-sm shrink-0">
                        {member.name[0]}
                      </div>
                      <div>
                        <p className="font-bold text-slate-800 group-hover:text-indigo-600 transition-colors text-sm">{member.name}</p>
                        <div className="flex items-center gap-1.5 text-[9px] text-slate-400 font-bold uppercase mt-1">
                          <span className="bg-slate-100 px-1 rounded text-slate-500">{member.gender || 'N/I'}</span>
                          <span className="mx-1">•</span>
                          <UserCheck className="w-2.5 h-2.5" /> {getLeaderName(member.responsible_leader_id)}
                        </div>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-5">
                    <div className="flex flex-col gap-1.5 items-start">
                      {getStageBadge(member.stage)}
                      <div className="flex items-center gap-1 text-[9px] text-slate-400 uppercase font-black ml-1">
                        {member.channel || 'MANUAL'}
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-5">
                    {member.interests ? (
                      <span className="px-2.5 py-1 bg-indigo-50 text-indigo-600 rounded-lg text-[10px] font-bold italic border border-indigo-100">
                        #{member.interests}
                      </span>
                    ) : (
                      <span className="text-slate-300 text-[10px] font-medium italic">Não informado</span>
                    )}
                  </td>
                  <td className="px-8 py-5">
                    <div className="flex items-center justify-end gap-3">
                      <button 
                        onClick={() => onQuickTask?.(member)}
                        className="p-2.5 text-indigo-500 hover:bg-indigo-100 rounded-xl transition-all shadow-sm bg-indigo-50/50"
                        title="Agendar Atividade"
                      >
                        <CalendarPlus className="w-5 h-5" />
                      </button>
                      <a 
                        href={`https://wa.me/${member.phone?.replace(/\D/g,'')}`}
                        target="_blank"
                        rel="noreferrer"
                        className="p-2.5 text-emerald-500 hover:bg-emerald-100 rounded-xl transition-all shadow-sm bg-emerald-50/50"
                        title="Enviar WhatsApp"
                      >
                        <MessageCircle className="w-5 h-5" />
                      </a>
                      <a 
                        href={`mailto:${member.email}`}
                        className="p-2.5 text-blue-500 hover:bg-blue-100 rounded-xl transition-all shadow-sm bg-blue-50/50"
                        title="Enviar E-mail"
                      >
                        <Mail className="w-5 h-5" />
                      </a>
                      <button 
                        onClick={() => onEditMember(member)}
                        className="p-2.5 text-slate-400 hover:text-indigo-600 hover:bg-slate-100 rounded-xl transition-all"
                        title="Editar Cadastro"
                      >
                        <Edit3 className="w-5 h-5" />
                      </button>
                      <button 
                        onClick={() => onDeleteMember(member.id)}
                        className="p-2.5 text-rose-400 hover:text-rose-600 hover:bg-rose-50 rounded-xl transition-all"
                        title="Remover Contato"
                      >
                        <Trash2 className="w-5 h-5" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          {filteredMembers.length === 0 && (
            <div className="py-20 flex flex-col items-center justify-center text-slate-300 gap-4">
              <Users className="w-16 h-16 opacity-10" />
              <p className="font-bold text-[10px] uppercase tracking-widest">Nenhum registro encontrado</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ContactsModule;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Columns, 
  Zap, 
  Settings, 
  Search, 
  LogOut,
  Menu,
  X,
  Shield,
  CalendarDays,
  Users,
  Church as ChurchIcon
} from 'lucide-react';
import KanbanBoard from './components/KanbanBoard';
import AnalyticsDashboard from './components/AnalyticsDashboard';
import AutomationSettings from './components/AutomationSettings';
import ScheduleModule from './components/ScheduleModule';
import MemberModal from './components/MemberModal';
import EventModal from './components/EventModal';
import ContactsModule from './components/ContactsModule';
import LoginScreen from './components/LoginScreen';
import ChurchModule from './components/ChurchModule';
import TeamModule from './components/TeamModule';
import SettingsModule from './components/SettingsModule';
import { Member, MemberStage, SystemUser, ScheduleEvent, EventType } from './types';
import { KoinoniaDB } from './services/db';

const navItems = [
  { id: 'analytics', label: 'Dashboard', icon: <LayoutDashboard className="w-5 h-5" /> },
  { id: 'kanban', label: 'Pipeline', icon: <Columns className="w-5 h-5" /> },
  { id: 'contacts', label: 'Contatos', icon: <Users className="w-5 h-5" /> },
  { id: 'agenda', label: 'Agenda', icon: <CalendarDays className="w-5 h-5" /> },
  { id: 'church', label: 'Igreja', icon: <ChurchIcon className="w-5 h-5" /> },
  { id: 'team', label: 'Equipe', icon: <Shield className="w-5 h-5" /> },
  { id: 'automation', label: 'IA & Automação', icon: <Zap className="w-5 h-5" /> },
  { id: 'settings', label: 'Ajustes', icon: <Settings className="w-5 h-5" /> },
];

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [activeTab, setActiveTab] = useState<string>('analytics');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [currentUser, setCurrentUser] = useState<SystemUser | null>(null);
  const [members, setMembers] = useState<Member[]>([]);
  const [events, setEvents] = useState<ScheduleEvent[]>([]);
  const [team, setTeam] = useState<SystemUser[]>([]);

  // Modals state
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [isEventModalOpen, setIsEventModalOpen] = useState(false);
  const [selectedMember, setSelectedMember] = useState<Member | null>(null);
  const [selectedEvent, setSelectedEvent] = useState<ScheduleEvent | null>(null);

  useEffect(() => {
    setMembers(KoinoniaDB.getAllMembers());
    setEvents(KoinoniaDB.getAllEvents());
    setTeam(KoinoniaDB.getAllUsers());

    const savedUser = localStorage.getItem('koinonia_session');
    if (savedUser) {
      setCurrentUser(JSON.parse(savedUser));
      setIsLoggedIn(true);
    }
  }, [activeTab]);

  const handleLoginSuccess = (user: SystemUser) => {
    setCurrentUser(user);
    localStorage.setItem('koinonia_session', JSON.stringify(user));
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    localStorage.removeItem('koinonia_session');
    setIsLoggedIn(false);
    setCurrentUser(null);
  };

  const handleSaveMember = (memberData: Partial<Member>) => {
    let updated;
    if (memberData.id) {
      updated = members.map(m => m.id === memberData.id ? { ...m, ...memberData } as Member : m);
    } else {
      const newMember: Member = {
        ...memberData,
        id: Math.random().toString(36).substr(2, 9),
        registration_date: new Date(),
        last_activity: new Date(),
        engagement_score: 50,
        church_id: currentUser?.church_id || 'default'
      } as Member;
      updated = [...members, newMember];
    }
    setMembers(updated);
    KoinoniaDB.saveMembers(updated);
    setIsMemberModalOpen(false);
    setSelectedMember(null);
  };

  const handleImportMembers = (newMembers: Member[]) => {
    const updated = [...members, ...newMembers];
    setMembers(updated);
    KoinoniaDB.saveMembers(updated);
    alert(`${newMembers.length} contatos importados com sucesso!`);
  };

  const handleDeleteMember = (id: string) => {
    if (window.confirm('Excluir este contato permanentemente?')) {
      const updated = members.filter(m => m.id !== id);
      setMembers(updated);
      KoinoniaDB.saveMembers(updated);
    }
  };

  const handleSaveEvent = (eventData: Partial<ScheduleEvent>) => {
    let updated;
    if (eventData.id) {
      updated = events.map(e => e.id === eventData.id ? { ...e, ...eventData } as ScheduleEvent : e);
    } else {
      const newEvent: ScheduleEvent = {
        ...eventData,
        id: Math.random().toString(36).substr(2, 9),
        created_at: new Date(),
        church_id: currentUser?.church_id || 'default'
      } as ScheduleEvent;
      updated = [...events, newEvent];
    }
    setEvents(updated);
    KoinoniaDB.saveEvents(updated);
    setIsEventModalOpen(false);
    setSelectedEvent(null);
  };

  const handleDeleteEvent = (id: string) => {
    if (window.confirm('Deseja excluir este agendamento definitivamente?')) {
      const updated = events.filter(e => e.id !== id);
      setEvents(updated);
      KoinoniaDB.saveEvents(updated);
    }
  };

  const handleQuickAddTask = (member: Member) => {
    setSelectedEvent({
      id: '',
      title: `Acompanhamento: ${member.name}`,
      description: `Acompanhamento de jornada agendado via módulo de contatos.`,
      type: EventType.FOLLOW_UP,
      start_date: new Date(),
      end_date: new Date(new Date().getTime() + 60 * 60 * 1000),
      member_id: member.id,
      responsible_id: member.responsible_leader_id || currentUser?.id,
      church_id: currentUser?.church_id || 'default',
      created_at: new Date()
    } as ScheduleEvent);
    setIsEventModalOpen(true);
  };

  const moveMember = (id: string, nextStage: MemberStage) => {
    const updated = members.map(m => m.id === id ? { ...m, stage: nextStage, last_activity: new Date() } : m);
    setMembers(updated);
    KoinoniaDB.saveMembers(updated);
  };

  if (!isLoggedIn) {
    return <LoginScreen onLogin={handleLoginSuccess} />;
  }

  return (
    <div className="flex h-screen bg-white overflow-hidden font-inter">
      <aside className={`${isSidebarOpen ? 'w-80' : 'w-24'} bg-slate-900 transition-all duration-500 flex flex-col z-50 shadow-2xl relative`}>
        <div className="p-10 flex items-center gap-5">
          <div className="w-12 h-12 bg-indigo-500 rounded-[18px] flex items-center justify-center shrink-0 shadow-lg shadow-indigo-500/30">
            <Shield className="w-6 h-6 text-white" />
          </div>
          {isSidebarOpen && <span className="font-black text-2xl text-white tracking-tight uppercase">Koinonia</span>}
        </div>

        <nav className="flex-1 px-8 py-6 space-y-2 overflow-y-auto scrollbar-hide">
          {navItems.map(item => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-5 px-5 py-4 rounded-[24px] transition-all group ${
                activeTab === item.id 
                  ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/30' 
                  : 'text-slate-500 hover:bg-slate-800 hover:text-white'
              }`}
            >
              <div className={`${activeTab === item.id ? 'text-white' : 'text-slate-500 group-hover:text-indigo-400'} transition-colors`}>
                {item.icon}
              </div>
              {isSidebarOpen && <span className="font-black text-[10px] uppercase tracking-[0.15em]">{item.label}</span>}
            </button>
          ))}
        </nav>

        <div className="p-8 border-t border-slate-800">
           <button onClick={handleLogout} className="w-full flex items-center gap-5 px-5 py-4 rounded-[24px] text-rose-400 hover:bg-rose-500/10 transition-all group">
             <LogOut className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
             {isSidebarOpen && <span className="font-black text-[10px] uppercase tracking-[0.15em]">Sair</span>}
           </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-slate-50 overflow-hidden">
        <header className="h-24 bg-white border-b border-slate-100 flex items-center justify-between px-12 shrink-0 z-40">
          <div className="flex items-center gap-8">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-3 hover:bg-slate-50 rounded-2xl text-slate-400 transition-all">
              {isSidebarOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
            <div>
              <h2 className="text-2xl font-black text-slate-800 tracking-tighter uppercase">
                {navItems.find(i => i.id === activeTab)?.label}
              </h2>
            </div>
          </div>

          <div className="flex items-center gap-8">
            <div className="relative group hidden sm:block">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
              <input 
                type="text" 
                placeholder="Pesquisa rápida..." 
                className="pl-12 pr-6 py-3 bg-slate-50 border-none rounded-2xl w-64 text-sm font-medium text-slate-700 focus:ring-2 focus:ring-indigo-500 transition-all" 
              />
            </div>

            <div className="relative">
              <button 
                onClick={() => setIsProfileOpen(!isProfileOpen)}
                className="flex items-center gap-4 p-2 pl-5 bg-slate-50 rounded-[28px] border border-slate-100 hover:bg-white hover:shadow-lg hover:shadow-indigo-50 transition-all"
              >
                <div className="text-right">
                  <p className="text-[11px] font-black text-slate-800 leading-none">{currentUser?.name}</p>
                  <p className="text-[8px] font-bold text-indigo-500 uppercase tracking-widest mt-1">{currentUser?.role}</p>
                </div>
                <div className="w-12 h-12 rounded-[20px] bg-indigo-600 flex items-center justify-center text-white font-black shadow-lg shadow-indigo-100">
                  {currentUser?.name?.[0]}
                </div>
              </button>

              {isProfileOpen && (
                <div className="absolute right-0 mt-3 w-64 bg-white rounded-[32px] shadow-2xl border border-slate-100 py-4 z-50 animate-in slide-in-from-top-2 duration-300">
                  <div className="px-6 py-3 border-b border-slate-50 mb-2">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Acesso Logado</p>
                    <p className="text-xs font-bold text-slate-700 mt-1">{currentUser?.email}</p>
                  </div>
                  <button onClick={() => { setActiveTab('settings'); setIsProfileOpen(false); }} className="w-full text-left px-6 py-3 text-xs font-bold text-slate-600 hover:bg-slate-50 hover:text-indigo-600 transition-all">Perfil</button>
                  <button onClick={handleLogout} className="w-full text-left px-6 py-3 text-xs font-bold text-rose-500 hover:bg-rose-50 transition-all">Sair</button>
                </div>
              )}
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-hidden relative">
          {activeTab === 'analytics' && <AnalyticsDashboard members={members} />}
          {activeTab === 'contacts' && (
            <ContactsModule 
              members={members} 
              team={team}
              onEditMember={(m) => { setSelectedMember(m); setIsMemberModalOpen(true); }}
              onDeleteMember={handleDeleteMember}
              onAddMember={() => { setSelectedMember(null); setIsMemberModalOpen(true); }}
              onImportMembers={handleImportMembers}
              onQuickTask={handleQuickAddTask}
            />
          )}
          {activeTab === 'kanban' && (
            <KanbanBoard 
              members={members} 
              events={events}
              team={team}
              onMoveMember={moveMember} 
              onAddMember={() => { setSelectedMember(null); setIsMemberModalOpen(true); }}
              onMemberClick={(m) => { setSelectedMember(m); setIsMemberModalOpen(true); }}
              onEditEvent={(e) => { setSelectedEvent(e); setIsEventModalOpen(true); }}
              onAddTask={handleQuickAddTask}
            />
          )}
          {activeTab === 'agenda' && (
            <ScheduleModule 
              events={events} 
              team={team}
              onAddEvent={() => { setSelectedEvent(null); setIsEventModalOpen(true); }}
              onEditEvent={(e) => { setSelectedEvent(e); setIsEventModalOpen(true); }}
              onDeleteEvent={handleDeleteEvent}
            />
          )}
          {activeTab === 'church' && <ChurchModule churchId={currentUser?.church_id || 'default'} />}
          {activeTab === 'team' && <TeamModule />}
          {activeTab === 'automation' && <AutomationSettings />}
          {activeTab === 'settings' && <SettingsModule />}
        </div>

        <MemberModal 
          isOpen={isMemberModalOpen} 
          onClose={() => setIsMemberModalOpen(false)} 
          onSave={handleSaveMember} 
          initialData={selectedMember} 
          team={team}
          events={events}
          onEditEvent={(e) => { setSelectedEvent(e); setIsEventModalOpen(true); }}
          onDeleteEvent={handleDeleteEvent}
        />
        <EventModal 
          isOpen={isEventModalOpen} 
          onClose={() => setIsEventModalOpen(false)} 
          onSave={handleSaveEvent} 
          initialData={selectedEvent} 
          team={team}
        />
      </main>
    </div>
  );
};

export default App;

