          onSave={handleSaveEvent} 
          initialData={selectedEvent} 
          team={team}
        />
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { X, Save, User, Mail, Phone, Tag, UserCheck, Heart, ChevronDown, History, Edit3, Trash2, Clock, FileText, Users2, MapPin, Search, Loader2 } from 'lucide-react';
import { Member, MemberStage, SystemUser, ScheduleEvent } from '../types';
import { STAGES } from '../constants';

interface MemberModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (member: Partial<Member>) => void;
  initialData?: Member | null;
  team?: SystemUser[];
  events?: ScheduleEvent[];
  onEditEvent?: (event: ScheduleEvent) => void;
  onDeleteEvent?: (id: string) => void;
}

const MemberModal: React.FC<MemberModalProps> = ({ 
  isOpen, 
  onClose, 
  onSave, 
  initialData, 
  team = [], 
  events = [],
  onEditEvent,
  onDeleteEvent
}) => {
  const [isLoadingCep, setIsLoadingCep] = useState(false);
  const [formData, setFormData] = useState<Partial<Member>>({
    name: '',
    email: '',
    phone: '',
    gender: '',
    stage: MemberStage.NEW,
    religion: '',
    address: '',
    channel: 'MANUAL',
    interests: '',
    responsible_leader_id: '',
    notes: ''
  });

  useEffect(() => {
    if (initialData) {
      setFormData(initialData);
    } else {
      setFormData({
        name: '', email: '', phone: '', gender: '', stage: MemberStage.NEW,
        religion: '', address: '', channel: 'MANUAL', interests: '',
        responsible_leader_id: '', notes: ''
      });
    }
  }, [initialData, isOpen]);

  const handleCepLookup = async (cep: string) => {
    const cleanCep = cep.replace(/\D/g, '');
    if (cleanCep.length === 8) {
      setIsLoadingCep(true);
      try {
        const response = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`);
        const data = await response.json();

        if (!data.erro) {
          const newAddress = `${data.logradouro}${data.bairro ? ', ' + data.bairro : ''} - ${data.localidade}/${data.uf}`;
          setFormData(prev => ({...prev, address: newAddress}));
        }
      } catch (error) {
        console.error("Erro ao buscar CEP:", error);
      } finally {
        setIsLoadingCep(false);
      }
    }
  };

  const memberEvents = events
    .filter(e => e.member_id === initialData?.id)
    .sort((a, b) => b.start_date.getTime() - a.start_date.getTime());

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
      <div className="bg-white w-full max-w-2xl rounded-[40px] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">
        <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-indigo-50/30 shrink-0">
          <div className="flex items-center gap-4">
            <div className="p-3 bg-indigo-600 rounded-2xl text-white shadow-lg shadow-indigo-200">
              <User className="w-6 h-6" />
            </div>
            <div>
              <h3 className="text-2xl font-black text-slate-800">
                {initialData ? 'Perfil do Contato' : 'Novo Cadastro'}
              </h3>
              <p className="text-xs font-bold text-indigo-500 uppercase tracking-widest">Jornada de Crescimento</p>
            </div>
          </div>
          <button onClick={onClose} className="p-3 hover:bg-white rounded-2xl text-slate-400 transition-all">
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-8 scrollbar-thin">
          <form onSubmit={(e) => { e.preventDefault(); onSave(formData); }} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              <div className="space-y-1 md:col-span-2">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Nome Completo</label>
                <input 
                  type="text" required
                  className="w-full px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all font-medium text-slate-800"
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  placeholder="Ex: João da Silva"
                />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">E-mail</label>
                <div className="relative">
                  <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                  <input 
                    type="email"
                    className="w-full pl-12 pr-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-slate-800 font-medium"
                    value={formData.email}
                    onChange={e => setFormData({...formData, email: e.target.value})}
                    placeholder="exemplo@email.com"
                  />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">WhatsApp / Telefone</label>
                <div className="relative">
                  <Phone className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                  <input 
                    type="text"
                    className="w-full pl-12 pr-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-slate-800 font-medium"
                    value={formData.phone}
                    onChange={e => setFormData({...formData, phone: e.target.value})}
                    placeholder="(00) 00000-0000"
                  />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Sexo / Gênero</label>
                <div className="relative">
                  <Users2 className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                  <select 
                    className="w-full pl-12 pr-10 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none appearance-none font-bold text-slate-700"
                    value={formData.gender || ''}
                    onChange={e => setFormData({...formData, gender: e.target.value})}
