                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Origem / Canal</label>
                <div className="relative">
                  <input 
                    list="channel-options-modal"
                    className="w-full px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-medium text-slate-800"
                    value={formData.channel || ''}
                    onChange={e => setFormData({...formData, channel: e.target.value})}
                    placeholder="Selecione ou digite..."
                  />
                  <datalist id="channel-options-modal">
                    <option value="MANUAL" />
                    <option value="CSV_IMPORT" />
                    <option value="QR_CODE" />
                    <option value="INSTAGRAM" />
                    <option value="WEBSITE" />
                    <option value="INDICATION" />
                    <option value="VISITA_PRESENCIAL" />
                  </datalist>
                  <Tag className="absolute right-4 top-1/2 -translate-y-1/2 w-3 h-3 text-slate-300 pointer-events-none" />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Estágio na Jornada</label>
                <div className="relative">
                  <select 
                    className="w-full px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none appearance-none font-black text-indigo-600 uppercase tracking-widest text-[10px]"
                    value={formData.stage}
                    onChange={e => setFormData({...formData, stage: e.target.value as MemberStage})}
                  >
                    {STAGES.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}
                  </select>
                  <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-3 h-3 text-indigo-400 pointer-events-none" />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Líder Responsável</label>
                <div className="relative">
                  <UserCheck className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                  <select 
                    className="w-full pl-12 pr-10 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none appearance-none font-bold text-slate-700"
