import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Columns, 
  Zap, 
  Settings, 
  Search, 
  LogOut,
  Menu,
  X,
  Shield,
  CalendarDays,
  Users,
  Church as ChurchIcon
} from 'lucide-react';
import KanbanBoard from './components/KanbanBoard';
import AnalyticsDashboard from './components/AnalyticsDashboard';
import AutomationSettings from './components/AutomationSettings';
import ScheduleModule from './components/ScheduleModule';
import MemberModal from './components/MemberModal';
import EventModal from './components/EventModal';
import ContactsModule from './components/ContactsModule';
import LoginScreen from './components/LoginScreen';
import ChurchModule from './components/ChurchModule';
import TeamModule from './components/TeamModule';
import SettingsModule from './components/SettingsModule';
import { Member, MemberStage, SystemUser, ScheduleEvent, EventType } from './types';
import { KoinoniaDB } from './services/db';

const navItems = [
  { id: 'analytics', label: 'Dashboard', icon: <LayoutDashboard className="w-5 h-5" /> },
  { id: 'kanban', label: 'Pipeline', icon: <Columns className="w-5 h-5" /> },
  { id: 'contacts', label: 'Contatos', icon: <Users className="w-5 h-5" /> },
  { id: 'agenda', label: 'Agenda', icon: <CalendarDays className="w-5 h-5" /> },
  { id: 'church', label: 'Igreja', icon: <ChurchIcon className="w-5 h-5" /> },
  { id: 'team', label: 'Equipe', icon: <Shield className="w-5 h-5" /> },
  { id: 'automation', label: 'IA & Automação', icon: <Zap className="w-5 h-5" /> },
  { id: 'settings', label: 'Ajustes', icon: <Settings className="w-5 h-5" /> },
];

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [activeTab, setActiveTab] = useState<string>('analytics');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [currentUser, setCurrentUser] = useState<SystemUser | null>(null);
  const [members, setMembers] = useState<Member[]>([]);
  const [events, setEvents] = useState<ScheduleEvent[]>([]);
  const [team, setTeam] = useState<SystemUser[]>([]);

  // Modals state
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [isEventModalOpen, setIsEventModalOpen] = useState(false);
  const [selectedMember, setSelectedMember] = useState<Member | null>(null);
  const [selectedEvent, setSelectedEvent] = useState<ScheduleEvent | null>(null);

  useEffect(() => {
    setMembers(KoinoniaDB.getAllMembers());
    setEvents(KoinoniaDB.getAllEvents());
    setTeam(KoinoniaDB.getAllUsers());

    const savedUser = localStorage.getItem('koinonia_session');
    if (savedUser) {
      setCurrentUser(JSON.parse(savedUser));
      setIsLoggedIn(true);
    }
  }, [activeTab]);

  const handleLoginSuccess = (user: SystemUser) => {
    setCurrentUser(user);
    localStorage.setItem('koinonia_session', JSON.stringify(user));
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    localStorage.removeItem('koinonia_session');
    setIsLoggedIn(false);
    setCurrentUser(null);
  };

  const handleSaveMember = (memberData: Partial<Member>) => {
    let updated;
    if (memberData.id) {
      updated = members.map(m => m.id === memberData.id ? { ...m, ...memberData } as Member : m);
    } else {
      const newMember: Member = {
        ...memberData,
        id: Math.random().toString(36).substr(2, 9),
        registration_date: new Date(),
        last_activity: new Date(),
        engagement_score: 50,
        church_id: currentUser?.church_id || 'default'
      } as Member;
      updated = [...members, newMember];
    }
    setMembers(updated);
    KoinoniaDB.saveMembers(updated);
    setIsMemberModalOpen(false);
    setSelectedMember(null);
  };

  const handleImportMembers = (newMembers: Member[]) => {
    const updated = [...members, ...newMembers];
    setMembers(updated);
    KoinoniaDB.saveMembers(updated);
    alert(`${newMembers.length} contatos importados com sucesso!`);
  };

  const handleDeleteMember = (id: string) => {
    if (window.confirm('Excluir este contato permanentemente?')) {
      const updated = members.filter(m => m.id !== id);
      setMembers(updated);
      KoinoniaDB.saveMembers(updated);
    }
  };

  const handleSaveEvent = (eventData: Partial<ScheduleEvent>) => {
    let updated;
    if (eventData.id) {
      updated = events.map(e => e.id === eventData.id ? { ...e, ...eventData } as ScheduleEvent : e);
    } else {
      const newEvent: ScheduleEvent = {
        ...eventData,
        id: Math.random().toString(36).substr(2, 9),
        created_at: new Date(),
        church_id: currentUser?.church_id || 'default'
      } as ScheduleEvent;
      updated = [...events, newEvent];
    }
    setEvents(updated);
    KoinoniaDB.saveEvents(updated);
    setIsEventModalOpen(false);
    setSelectedEvent(null);
  };

  const handleDeleteEvent = (id: string) => {
    if (window.confirm('Deseja excluir este agendamento definitivamente?')) {
      const updated = events.filter(e => e.id !== id);
      setEvents(updated);
      KoinoniaDB.saveEvents(updated);
    }
  };

  const handleQuickAddTask = (member: Member) => {
    setSelectedEvent({
      id: '',
      title: `Acompanhamento: ${member.name}`,
      description: `Acompanhamento de jornada agendado via módulo de contatos.`,
      type: EventType.FOLLOW_UP,
      start_date: new Date(),
      end_date: new Date(new Date().getTime() + 60 * 60 * 1000),
      member_id: member.id,
      responsible_id: member.responsible_leader_id || currentUser?.id,
      church_id: currentUser?.church_id || 'default',
      created_at: new Date()
    } as ScheduleEvent);
    setIsEventModalOpen(true);
  };

  const moveMember = (id: string, nextStage: MemberStage) => {
    const updated = members.map(m => m.id === id ? { ...m, stage: nextStage, last_activity: new Date() } : m);
    setMembers(updated);
    KoinoniaDB.saveMembers(updated);
  };

  if (!isLoggedIn) {
    return <LoginScreen onLogin={handleLoginSuccess} />;
  }

  return (
    <div className="flex h-screen bg-white overflow-hidden font-inter">
      <aside className={`${isSidebarOpen ? 'w-80' : 'w-24'} bg-slate-900 transition-all duration-500 flex flex-col z-50 shadow-2xl relative`}>
        <div className="p-10 flex items-center gap-5">
          <div className="w-12 h-12 bg-indigo-500 rounded-[18px] flex items-center justify-center shrink-0 shadow-lg shadow-indigo-500/30">
            <Shield className="w-6 h-6 text-white" />
          </div>
          {isSidebarOpen && <span className="font-black text-2xl text-white tracking-tight uppercase">Koinonia</span>}
        </div>

        <nav className="flex-1 px-8 py-6 space-y-2 overflow-y-auto scrollbar-hide">
          {navItems.map(item => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-5 px-5 py-4 rounded-[24px] transition-all group ${
                activeTab === item.id 
                  ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/30' 
                  : 'text-slate-500 hover:bg-slate-800 hover:text-white'
              }`}
            >
              <div className={`${activeTab === item.id ? 'text-white' : 'text-slate-500 group-hover:text-indigo-400'} transition-colors`}>
                {item.icon}
              </div>
              {isSidebarOpen && <span className="font-black text-[10px] uppercase tracking-[0.15em]">{item.label}</span>}
            </button>
          ))}
        </nav>

        <div className="p-8 border-t border-slate-800">
           <button onClick={handleLogout} className="w-full flex items-center gap-5 px-5 py-4 rounded-[24px] text-rose-400 hover:bg-rose-500/10 transition-all group">
             <LogOut className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
             {isSidebarOpen && <span className="font-black text-[10px] uppercase tracking-[0.15em]">Sair</span>}
           </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-slate-50 overflow-hidden">
        <header className="h-24 bg-white border-b border-slate-100 flex items-center justify-between px-12 shrink-0 z-40">
          <div className="flex items-center gap-8">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-3 hover:bg-slate-50 rounded-2xl text-slate-400 transition-all">
              {isSidebarOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
            <div>
              <h2 className="text-2xl font-black text-slate-800 tracking-tighter uppercase">
                {navItems.find(i => i.id === activeTab)?.label}
              </h2>
            </div>
          </div>

          <div className="flex items-center gap-8">
            <div className="relative group hidden sm:block">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
              <input 
                type="text" 
                placeholder="Pesquisa rápida..." 
                className="pl-12 pr-6 py-3 bg-slate-50 border-none rounded-2xl w-64 text-sm font-medium text-slate-700 focus:ring-2 focus:ring-indigo-500 transition-all" 
              />
            </div>

            <div className="relative">
              <button 
                onClick={() => setIsProfileOpen(!isProfileOpen)}
                className="flex items-center gap-4 p-2 pl-5 bg-slate-50 rounded-[28px] border border-slate-100 hover:bg-white hover:shadow-lg hover:shadow-indigo-50 transition-all"
              >
                <div className="text-right">
                  <p className="text-[11px] font-black text-slate-800 leading-none">{currentUser?.name}</p>
                  <p className="text-[8px] font-bold text-indigo-500 uppercase tracking-widest mt-1">{currentUser?.role}</p>
                </div>
                <div className="w-12 h-12 rounded-[20px] bg-indigo-600 flex items-center justify-center text-white font-black shadow-lg shadow-indigo-100">
                  {currentUser?.name?.[0]}
                </div>
              </button>

              {isProfileOpen && (
                <div className="absolute right-0 mt-3 w-64 bg-white rounded-[32px] shadow-2xl border border-slate-100 py-4 z-50 animate-in slide-in-from-top-2 duration-300">
                  <div className="px-6 py-3 border-b border-slate-50 mb-2">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Acesso Logado</p>
                    <p className="text-xs font-bold text-slate-700 mt-1">{currentUser?.email}</p>
                  </div>
                  <button onClick={() => { setActiveTab('settings'); setIsProfileOpen(false); }} className="w-full text-left px-6 py-3 text-xs font-bold text-slate-600 hover:bg-slate-50 hover:text-indigo-600 transition-all">Perfil</button>
                  <button onClick={handleLogout} className="w-full text-left px-6 py-3 text-xs font-bold text-rose-500 hover:bg-rose-50 transition-all">Sair</button>
                </div>
              )}
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-hidden relative">
          {activeTab === 'analytics' && <AnalyticsDashboard members={members} />}
          {activeTab === 'kanban' && (
            <KanbanBoard 
              members={members} 
              events={events}
              team={team}
              onMoveMember={moveMember} 
              onAddMember={() => { setSelectedMember(null); setIsMemberModalOpen(true); }}
              onMemberClick={(m) => { setSelectedMember(m); setIsMemberModalOpen(true); }}
              onEditEvent={(e) => { setSelectedEvent(e); setIsEventModalOpen(true); }}
              onAddTask={handleQuickAddTask}
            />
          )}
          {activeTab === 'contacts' && (
            <ContactsModule 
              members={members} 
              team={team}
              onEditMember={(m) => { setSelectedMember(m); setIsMemberModalOpen(true); }}
              onDeleteMember={handleDeleteMember}
              onAddMember={() => { setSelectedMember(null); setIsMemberModalOpen(true); }}
              onImportMembers={handleImportMembers}
              onQuickTask={handleQuickAddTask}
            />
          )}
          {activeTab === 'agenda' && (
            <ScheduleModule 
              events={events} 
              team={team}
              onAddEvent={() => { setSelectedEvent(null); setIsEventModalOpen(true); }}
              onEditEvent={(e) => { setSelectedEvent(e); setIsEventModalOpen(true); }}
              onDeleteEvent={handleDeleteEvent}
            />
          )}
          {activeTab === 'church' && <ChurchModule churchId={currentUser?.church_id || 'default'} />}
          {activeTab === 'team' && <TeamModule />}
          {activeTab === 'automation' && <AutomationSettings />}
          {activeTab === 'settings' && <SettingsModule />}
        </div>

        <MemberModal 
          isOpen={isMemberModalOpen} 
          onClose={() => setIsMemberModalOpen(false)} 
          onSave={handleSaveMember} 
          initialData={selectedMember} 
          team={team}
          events={events}
          onEditEvent={(e) => { setSelectedEvent(e); setIsEventModalOpen(true); }}
          onDeleteEvent={handleDeleteEvent}
        />
        <EventModal 
          isOpen={isEventModalOpen} 
          onClose={() => setIsEventModalOpen(false)} 
          onSave={handleSaveEvent} 
          initialData={selectedEvent} 
          team={team}
        />
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { X, Save, User, Mail, Phone, Tag, UserCheck, Heart, ChevronDown, History, Edit3, Trash2, Clock, FileText, Users2, MapPin, Search, Loader2 } from 'lucide-react';
import { Member, MemberStage, SystemUser, ScheduleEvent } from '../types';
import { STAGES } from '../constants';

interface MemberModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (member: Partial<Member>) => void;
  initialData?: Member | null;
  team?: SystemUser[];
  events?: ScheduleEvent[];
  onEditEvent?: (event: ScheduleEvent) => void;
  onDeleteEvent?: (id: string) => void;
}

const MemberModal: React.FC<MemberModalProps> = ({ 
  isOpen, 
  onClose, 
  onSave, 
  initialData, 
  team = [], 
  events = [],
  onEditEvent,
  onDeleteEvent
}) => {
  const [isLoadingCep, setIsLoadingCep] = useState(false);
  const [formData, setFormData] = useState<Partial<Member>>({
    name: '',
    email: '',
    phone: '',
    cep: '',
    gender: '',
    stage: MemberStage.NEW,
    religion: '',
    address: '',
    channel: 'MANUAL',
    interests: '',
    responsible_leader_id: '',
    notes: ''
  });

  useEffect(() => {
    if (initialData) {
      setFormData(initialData);
    } else {
      setFormData({
        name: '', email: '', phone: '', cep: '', gender: '', stage: MemberStage.NEW,
        religion: '', address: '', channel: 'MANUAL', interests: '',
        responsible_leader_id: '', notes: ''
      });
    }
  }, [initialData, isOpen]);

  const applyCepMask = (value: string) => {
    return value
      .replace(/\D/g, '')
      .replace(/(\d{5})(\d)/, '$1-$2')
      .slice(0, 9);
  };

  const handleCepChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const maskedValue = applyCepMask(e.target.value);
    setFormData(prev => ({ ...prev, cep: maskedValue }));

    if (maskedValue.length === 9) {
      handleCepLookup(maskedValue);
    }
  };

  const handleCepLookup = async (cep: string) => {
    const cleanCep = cep.replace(/\D/g, '');
    if (cleanCep.length === 8) {
      setIsLoadingCep(true);
      try {
        const response = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`);
        const data = await response.json();

        if (!data.erro) {
          const newAddress = `${data.logradouro}${data.bairro ? ', ' + data.bairro : ''} - ${data.localidade}/${data.uf}`;
          setFormData(prev => ({...prev, address: newAddress}));
        }
      } catch (error) {
        console.error("Erro ao buscar CEP:", error);
      } finally {
        setIsLoadingCep(false);
      }
    }
  };

  const memberEvents = events
    .filter(e => e.member_id === initialData?.id)
    .sort((a, b) => b.start_date.getTime() - a.start_date.getTime());

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
      <div className="bg-white w-full max-w-2xl rounded-[40px] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">
        <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-indigo-50/30 shrink-0">
          <div className="flex items-center gap-4">
            <div className="p-3 bg-indigo-600 rounded-2xl text-white shadow-lg shadow-indigo-200">
              <User className="w-6 h-6" />
            </div>
            <div>
              <h3 className="text-2xl font-black text-slate-800">
                {initialData ? 'Perfil do Contato' : 'Novo Cadastro'}
              </h3>
              <p className="text-xs font-bold text-indigo-500 uppercase tracking-widest">Jornada de Crescimento</p>
            </div>
          </div>
          <button onClick={onClose} className="p-3 hover:bg-white rounded-2xl text-slate-400 transition-all">
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-8 scrollbar-thin">
          <form onSubmit={(e) => { e.preventDefault(); onSave(formData); }} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              <div className="space-y-1 md:col-span-2">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Nome Completo</label>
                <input 
                  type="text" required
                  className="w-full px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all font-medium text-slate-800"
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  placeholder="Ex: João da Silva"
                />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">E-mail</label>
                <div className="relative">
                  <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                  <input 
                    type="email"
                    className="w-full pl-12 pr-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-slate-800 font-medium"
                    value={formData.email}
                    onChange={e => setFormData({...formData, email: e.target.value})}
                    placeholder="exemplo@email.com"
                  />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">WhatsApp / Telefone</label>
                <div className="relative">
                  <Phone className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                  <input 
                    type="text"
                    className="w-full pl-12 pr-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-slate-800 font-medium"
                    value={formData.phone}
                    onChange={e => setFormData({...formData, phone: e.target.value})}
                    placeholder="(00) 00000-0000"
                  />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Sexo / Gênero</label>
                <div className="relative">
                  <Users2 className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                  <select 
                    className="w-full pl-12 pr-10 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none appearance-none font-bold text-slate-700"
                    value={formData.gender || ''}
                    onChange={e => setFormData({...formData, gender: e.target.value})}
                  >
                    <option value="">Selecione...</option>
                    <option value="Masculino">Masculino</option>
                    <option value="Feminino">Feminino</option>
                    <option value="Outro">Outro</option>
                  </select>
                  <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-3 h-3 text-slate-400 pointer-events-none" />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Interesses / Ministérios</label>
                <div className="relative">
                  <Heart className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                  <input 
                    type="text"
                    className="w-full pl-12 pr-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-slate-800 font-medium"
                    value={formData.interests || ''}
                    onChange={e => setFormData({...formData, interests: e.target.value})}
                    placeholder="Ex: Estudos Bíblicos, Louvor..."
                  />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">CEP (Busca Automática)</label>
                <div className="relative">
                  <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                  <input 
                    type="text"
                    className="w-full pl-11 pr-10 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-medium text-slate-800"
                    value={formData.cep || ''}
                    onChange={handleCepChange}
                    placeholder="12233-680"
                  />
                  {isLoadingCep && <Loader2 className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-indigo-500 animate-spin" />}
                </div>
              </div>

              <div className="space-y-1 md:col-span-2">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Endereço Completo</label>
                <div className="relative">
                  <MapPin className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                  <input 
                    type="text"
                    className="w-full pl-12 pr-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-slate-800 font-medium"
                    value={formData.address || ''}
                    onChange={e => setFormData({...formData, address: e.target.value})}
                    placeholder="Rua, número, bairro..."
                  />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Origem / Canal</label>
                <div className="relative">
                  <input 
                    list="channel-options-modal"
                    className="w-full px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-medium text-slate-800"
                    value={formData.channel || ''}
                    onChange={e => setFormData({...formData, channel: e.target.value})}
                    placeholder="Selecione ou digite..."
                  />
                  <datalist id="channel-options-modal">
                    <option value="MANUAL" />
                    <option value="CSV_IMPORT" />
                    <option value="QR_CODE" />
                    <option value="INSTAGRAM" />
                    <option value="WEBSITE" />
                    <option value="INDICATION" />
                    <option value="VISITA_PRESENCIAL" />
                  </datalist>
                  <Tag className="absolute right-4 top-1/2 -translate-y-1/2 w-3 h-3 text-slate-300 pointer-events-none" />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Estágio na Jornada</label>
                <div className="relative">
                  <select 
                    className="w-full px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none appearance-none font-black text-indigo-600 uppercase tracking-widest text-[10px]"
                    value={formData.stage}
                    onChange={e => setFormData({...formData, stage: e.target.value as MemberStage})}
                  >
                    {STAGES.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}
                  </select>
                  <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-3 h-3 text-indigo-400 pointer-events-none" />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Líder Responsável</label>
                <div className="relative">
                  <UserCheck className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                  <select 
                    className="w-full pl-12 pr-10 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none appearance-none font-bold text-slate-700"
                    value={formData.responsible_leader_id || ''}
                    onChange={e => setFormData({...formData, responsible_leader_id: e.target.value})}
                  >
                    <option value="">Sem líder atribuído</option>
                    {team.map(u => <option key={u.id} value={u.id}>{u.name}</option>)}
                  </select>
                  <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-3 h-3 text-slate-400 pointer-events-none" />
                </div>
              </div>

              <div className="space-y-1 md:col-span-2">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Notas e Comentários</label>
                <div className="relative">
                  <FileText className="absolute left-4 top-4 w-4 h-4 text-slate-400" />
                  <textarea 
                    className="w-full pl-12 pr-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all resize-none text-slate-800 font-medium text-sm"
                    rows={3}
                    placeholder="Detalhes relevantes sobre o acompanhamento..."
                    value={formData.notes || ''}
                    onChange={e => setFormData({...formData, notes: e.target.value})}
                  />
                </div>
              </div>
            </div>

            <div className="flex gap-4">
              <button 
                type="submit"
                className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl font-black shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all flex items-center justify-center gap-3 uppercase tracking-widest text-[10px]"
              >
                <Save className="w-5 h-5" /> Salvar Cadastro
              </button>
            </div>
          </form>

          {initialData && (
            <div className="space-y-4 pt-8 border-t border-slate-100">
              <div className="flex items-center gap-2 mb-4">
                <History className="w-5 h-5 text-slate-400" />
                <h4 className="text-sm font-black text-slate-700 uppercase tracking-widest">Histórico de Atividades</h4>
              </div>

              <div className="space-y-3">
                {memberEvents.length > 0 ? (
                  memberEvents.map(event => (
                    <div key={event.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex items-center justify-between group">
                      <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-white rounded-xl border border-slate-100 flex flex-col items-center justify-center shrink-0">
                          <span className="text-[8px] font-black text-slate-400 uppercase leading-none">{event.start_date.toLocaleDateString('pt-BR', {month: 'short'})}</span>
                          <span className="text-sm font-black text-slate-800">{event.start_date.getDate()}</span>
                        </div>
                        <div>
                          <p className="font-bold text-slate-800 text-xs">{event.title}</p>
                          <div className="flex items-center gap-2 mt-0.5 text-[10px] text-slate-400 font-medium">
                            <Clock className="w-3 h-3" />
                            {event.start_date.toLocaleTimeString('pt-BR', {hour: '2-digit', minute: '2-digit'})}
                          </div>
                        </div>
                      </div>
                      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button 
                          onClick={() => onEditEvent?.(event)}
                          className="p-2 text-indigo-500 hover:bg-indigo-100 rounded-lg transition-all"
                          title="Editar Agendamento"
                        >
                          <Edit3 className="w-4 h-4" />
                        </button>
                        <button 
                          onClick={() => onDeleteEvent?.(event.id)}
                          className="p-2 text-rose-500 hover:bg-rose-100 rounded-lg transition-all"
                          title="Excluir Agendamento"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="py-6 text-center bg-slate-50 rounded-2xl border border-dashed border-slate-200">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Nenhuma atividade registrada</p>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

