import React, { useState, useEffect } from 'react';
import { X, Save, Calendar, Clock, MapPin, Tag, UserCheck, ChevronDown } from 'lucide-react';
import { ScheduleEvent, EventType, SystemUser } from '../types';

interface EventModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (event: Partial<ScheduleEvent>) => void;
  initialData?: ScheduleEvent | null;
  defaultDate?: Date;
  team?: SystemUser[];
}

const eventTypeLabels: Record<EventType, string> = {
  [EventType.SERVICE]: 'Culto',
  [EventType.MEETING]: 'Reunião',
  [EventType.EVENT]: 'Evento',
  [EventType.FOLLOW_UP]: 'Acompanhamento',
  [EventType.VISIT]: 'Visita',
};

const EventModal: React.FC<EventModalProps> = ({ isOpen, onClose, onSave, initialData, defaultDate, team = [] }) => {
  const [formData, setFormData] = useState<Partial<ScheduleEvent>>({
    title: '',
    description: '',
    type: EventType.SERVICE,
    location: '',
    start_date: new Date(),
    end_date: new Date(new Date().getTime() + 60 * 60 * 1000),
    responsible_id: ''
  });

  // Função para formatar data para o input datetime-local respeitando o fuso horário local
  const formatToLocalISO = (date: Date) => {
    const tzOffset = date.getTimezoneOffset() * 60000;
    const localISOTime = new Date(date.getTime() - tzOffset).toISOString().slice(0, 16);
    return localISOTime;
  };

  useEffect(() => {
    if (initialData) {
      setFormData(initialData);
    } else if (defaultDate) {
      setFormData({
        title: '',
        description: '',
        type: EventType.SERVICE,
        location: '',
        start_date: defaultDate,
        end_date: new Date(defaultDate.getTime() + 60 * 60 * 1000),
        responsible_id: ''
      });
    }
  }, [initialData, defaultDate, isOpen]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-white w-full max-w-xl rounded-[32px] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-indigo-50/30">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-indigo-600 rounded-xl text-white">
              <Calendar className="w-5 h-5" />
            </div>
            <h3 className="text-xl font-black text-slate-800">
              {initialData ? 'Editar Compromisso' : 'Novo Compromisso'}
            </h3>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-white rounded-xl text-slate-400 transition-colors">
            <X className="w-6 h-6" />
          </button>
        </div>

        <form onSubmit={(e) => { e.preventDefault(); onSave(formData); }} className="p-8 space-y-5">
          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Título do Evento / Atividade</label>
            <input 
              type="text" required
              className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all text-slate-800 font-medium"
              value={formData.title}
              onChange={e => setFormData({...formData, title: e.target.value})}
              placeholder="Ex: Visita de Boas-vindas"
            />
          </div>

          <div className="grid grid-cols-2 gap-5">
            <div className="space-y-1">
              <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Tipo de Atividade</label>
              <div className="relative">
                <select 
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none appearance-none text-slate-800 font-bold text-xs uppercase tracking-widest"
                  value={formData.type}
                  onChange={e => setFormData({...formData, type: e.target.value as EventType})}
                >
                  {Object.values(EventType).map(type => (
                    <option key={type} value={type}>{eventTypeLabels[type]}</option>
                  ))}
                </select>
                <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-3 h-3 text-slate-400 pointer-events-none" />
              </div>
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Local</label>
              <div className="relative">
                <MapPin className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                <input 
                  type="text"
