                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[9px] font-black uppercase text-slate-400">E-mail</label>
                    <input type="email" required className="w-full px-4 py-3 bg-slate-50 border-none rounded-xl" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[9px] font-black uppercase text-slate-400">WhatsApp</label>
                    <input type="text" className="w-full px-4 py-3 bg-slate-50 border-none rounded-xl" value={formData.whatsapp} onChange={e => setFormData({...formData, whatsapp: e.target.value})} />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[9px] font-black uppercase text-slate-400">Nível de Acesso</label>
                    <select className="w-full px-4 py-3 bg-slate-50 border-none rounded-xl font-black text-[9px] uppercase" value={formData.role} onChange={e => setFormData({...formData, role: e.target.value as UserRole})}>
                      {Object.values(UserRole).map(role => <option key={role} value={role}>{role}</option>)}
                    </select>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[9px] font-black uppercase text-slate-400">Senha</label>
                    <input type="password" placeholder="••••••" className="w-full px-4 py-3 bg-slate-50 border-none rounded-xl" value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})} />
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black uppercase text-slate-400">Função Ministerial</label>
                  <input type="text" className="w-full px-4 py-3 bg-slate-50 border-none rounded-xl" value={formData.duty} onChange={e => setFormData({...formData, duty: e.target.value})} />
                </div>
              </div>
              <div className="pt-4 flex gap-3">
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 py-3 bg-slate-100 rounded-xl font-black text-[9px] uppercase">Cancelar</button>
                <button type="submit" className="flex-[2] py-3 bg-indigo-600 text-white rounded-xl font-black shadow-xl shadow-indigo-100 uppercase text-[9px]">Salvar Líder</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default TeamModule;

import React, { useState, useEffect, useRef } from 'react';
import { 
  LayoutDashboard, 
  Columns, 
  Zap, 
  Settings, 
  Search, 
  LogOut,
  Menu,
  X,
  Shield,
  CalendarDays,
  Users,
  Church as ChurchIcon
} from 'lucide-react';
import KanbanBoard from './components/KanbanBoard';
import AnalyticsDashboard from './components/AnalyticsDashboard';
import AutomationSettings from './components/AutomationSettings';
import ScheduleModule from './components/ScheduleModule';
import MemberModal from './components/MemberModal';
import EventModal from './components/EventModal';
import ContactsModule from './components/ContactsModule';
import LoginScreen from './components/LoginScreen';
import ChurchModule from './components/ChurchModule';
import TeamModule from './components/TeamModule';
import SettingsModule from './components/SettingsModule';
import { Member, MemberStage, SystemUser, ScheduleEvent, EventType } from './types';
import { KoinoniaDB } from './services/db';

const navItems = [
  { id: 'analytics', label: 'Dashboard', icon: <LayoutDashboard className="w-5 h-5" /> },
  { id: 'kanban', label: 'Pipeline', icon: <Columns className="w-5 h-5" /> },
  { id: 'contacts', label: 'Contatos', icon: <Users className="w-5 h-5" /> },
  { id: 'agenda', label: 'Agenda', icon: <CalendarDays className="w-5 h-5" /> },
  { id: 'church', label: 'Igreja', icon: <ChurchIcon className="w-5 h-5" /> },
  { id: 'team', label: 'Equipe', icon: <Shield className="w-5 h-5" /> },
  { id: 'automation', label: 'IA & Automação', icon: <Zap className="w-5 h-5" /> },
  { id: 'settings', label: 'Ajustes', icon: <Settings className="w-5 h-5" /> },
];

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [activeTab, setActiveTab] = useState<string>('analytics');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [currentUser, setCurrentUser] = useState<SystemUser | null>(null);

  // Estados carregados diretamente do DB
  const [members, setMembers] = useState<Member[]>(() => KoinoniaDB.getAllMembers());
  const [events, setEvents] = useState<ScheduleEvent[]>(() => KoinoniaDB.getAllEvents());
  const [team, setTeam] = useState<SystemUser[]>(() => KoinoniaDB.getAllUsers());

  // Refs para evitar loops de salvamento inicial
  const isInitialMount = useRef(true);

  // Modals state
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [isEventModalOpen, setIsEventModalOpen] = useState(false);
  const [selectedMember, setSelectedMember] = useState<Member | null>(null);
  const [selectedEvent, setSelectedEvent] = useState<ScheduleEvent | null>(null);

  // Efeito para persistência automática
  useEffect(() => {
    if (isInitialMount.current) {
      isInitialMount.current = false;
      // Carregar sessão
      const savedUser = localStorage.getItem('koinonia_session');
      if (savedUser) {
        setCurrentUser(JSON.parse(savedUser));
        setIsLoggedIn(true);
      }
      return;
    }
    KoinoniaDB.saveMembers(members);
    KoinoniaDB.saveEvents(events);
    KoinoniaDB.saveUsers(team);
  }, [members, events, team]);

  const handleLoginSuccess = (user: SystemUser) => {
    setCurrentUser(user);
    localStorage.setItem('koinonia_session', JSON.stringify(user));
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    localStorage.removeItem('koinonia_session');
    setIsLoggedIn(false);
    setCurrentUser(null);
  };

  // HANDLERS DE MEMBROS
  const handleSaveMember = (memberData: Partial<Member>) => {
    if (memberData.id) {
      setMembers(prev => prev.map(m => m.id === memberData.id ? { ...m, ...memberData } as Member : m));
    } else {
      const newMember: Member = {
        ...memberData,
        id: Math.random().toString(36).substr(2, 9),
        registration_date: new Date(),
        last_activity: new Date(),
        engagement_score: 50,
        church_id: currentUser?.church_id || 'default'
      } as Member;
      setMembers(prev => [...prev, newMember]);
    }
    setIsMemberModalOpen(false);
    setSelectedMember(null);
  };

  const handleDeleteMember = (id: string) => {
    if (window.confirm('Tem certeza que deseja excluir este contato? Esta ação não pode ser desfeita.')) {
      setMembers(prev => prev.filter(m => m.id !== id));
      // Se o modal estava aberto com esse membro, fecha
      if (selectedMember?.id === id) setIsMemberModalOpen(false);
    }
  };

  // HANDLERS DE EVENTOS (AGENDA / TAREFAS / ATIVIDADES)
  const handleSaveEvent = (eventData: Partial<ScheduleEvent>) => {
    const processedEvent = {
      ...eventData,
      start_date: eventData.start_date ? new Date(eventData.start_date) : new Date(),
      end_date: eventData.end_date ? new Date(eventData.end_date) : new Date(),
    };

    if (eventData.id) {
      setEvents(prev => prev.map(e => e.id === eventData.id ? { ...e, ...processedEvent } as ScheduleEvent : e));
    } else {
      const newEvent: ScheduleEvent = {
        ...processedEvent,
        id: Math.random().toString(36).substr(2, 9),
        created_at: new Date(),
        church_id: currentUser?.church_id || 'default'
      } as ScheduleEvent;
      setEvents(prev => [...prev, newEvent]);
    }
    setIsEventModalOpen(false);
    setSelectedEvent(null);
  };

  const handleDeleteEvent = (id: string) => {
    if (window.confirm('Deseja excluir permanentemente este compromisso/atividade?')) {
      setEvents(prev => {
        const filtered = prev.filter(e => e.id !== id);
        return filtered;
      });
      // Se o modal estava aberto com esse evento, fecha
      if (selectedEvent?.id === id) setIsEventModalOpen(false);
    }
  };

  // HANDLERS DE EQUIPE
  const handleSaveTeamMember = (userData: Partial<SystemUser>) => {
    if (userData.id) {
      setTeam(prev => prev.map(u => u.id === userData.id ? { ...u, ...userData } as SystemUser : u));
    } else {
      const newUser: SystemUser = {
        ...userData,
        id: Math.random().toString(36).substr(2, 9),
        church_id: currentUser?.church_id || 'default',
        permissions: ['standard'],
      } as SystemUser;
      setTeam(prev => [...prev, newUser]);
    }
  };

  const handleDeleteTeamMember = (id: string) => {
    if (window.confirm('Remover este líder da equipe de gestão?')) {
      setTeam(prev => prev.filter(u => u.id !== id));
    }
  };

  const handleQuickAddTask = (member: Member) => {
    setSelectedEvent({
      id: '',
      title: `Acomp: ${member.name}`,
      description: `Acompanhamento agendado via pipeline.`,
      type: EventType.FOLLOW_UP,
      start_date: new Date(),
      end_date: new Date(new Date().getTime() + 30 * 60 * 1000),
      member_id: member.id,
      responsible_id: member.responsible_leader_id || currentUser?.id,
      church_id: currentUser?.church_id || 'default',
      created_at: new Date()
    } as ScheduleEvent);
    setIsEventModalOpen(true);
  };

  const moveMember = (id: string, nextStage: MemberStage) => {
    setMembers(prev => prev.map(m => m.id === id ? { ...m, stage: nextStage, last_activity: new Date() } : m));
  };

  if (!isLoggedIn) {
    return <LoginScreen onLogin={handleLoginSuccess} />;
  }

  return (
    <div className="flex h-screen bg-white overflow-hidden font-inter">
      <aside className={`${isSidebarOpen ? 'w-80' : 'w-24'} bg-slate-900 transition-all duration-500 flex flex-col z-50 shadow-2xl relative`}>
        <div className="p-10 flex items-center gap-5">
          <div className="w-12 h-12 bg-indigo-500 rounded-[18px] flex items-center justify-center shadow-lg shadow-indigo-500/30 shrink-0">
            <Shield className="w-6 h-6 text-white" />
          </div>
          {isSidebarOpen && <span className="font-black text-2xl text-white tracking-tight uppercase truncate">Koinonia</span>}
        </div>

        <nav className="flex-1 px-8 py-6 space-y-2 overflow-y-auto scrollbar-hide">
          {navItems.map(item => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-5 px-5 py-4 rounded-[24px] transition-all group ${
                activeTab === item.id 
                  ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/30' 
                  : 'text-slate-500 hover:bg-slate-800 hover:text-white'
              }`}
            >
              <div className={`${activeTab === item.id ? 'text-white' : 'text-slate-500 group-hover:text-indigo-400'} transition-colors shrink-0`}>
                {item.icon}
              </div>
              {isSidebarOpen && <span className="font-black text-[10px] uppercase tracking-[0.15em] truncate">{item.label}</span>}
            </button>
          ))}
        </nav>

        <div className="p-8 border-t border-slate-800 shrink-0">
           <button onClick={handleLogout} className="w-full flex items-center gap-5 px-5 py-4 rounded-[24px] text-rose-400 hover:bg-rose-500/10 transition-all group">
             <LogOut className="w-5 h-5 group-hover:translate-x-1 transition-transform shrink-0" />
             {isSidebarOpen && <span className="font-black text-[10px] uppercase tracking-[0.15em]">Sair</span>}
           </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-slate-50 overflow-hidden">
        <header className="h-24 bg-white border-b border-slate-100 flex items-center justify-between px-12 shrink-0 z-40">
          <div className="flex items-center gap-8">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-3 hover:bg-slate-50 rounded-2xl text-slate-400 transition-all">
              {isSidebarOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
            <h2 className="text-2xl font-black text-slate-800 uppercase tracking-tighter truncate max-w-[200px] md:max-w-none">
              {navItems.find(i => i.id === activeTab)?.label}
            </h2>
          </div>

          <div className="flex items-center gap-8">
            <div className="relative">
              <button 
                onClick={() => setIsProfileOpen(!isProfileOpen)}
                className="flex items-center gap-4 p-2 bg-slate-50 rounded-[28px] border border-slate-100 hover:bg-white hover:shadow-lg transition-all"
              >
                <div className="text-right hidden md:block px-2">
                  <p className="text-[11px] font-black text-slate-800 leading-none truncate max-w-[120px]">{currentUser?.name}</p>
                  <p className="text-[8px] font-bold text-indigo-500 uppercase tracking-widest mt-1">{currentUser?.role}</p>
                </div>
                <div className="w-12 h-12 rounded-[20px] bg-indigo-600 flex items-center justify-center text-white font-black shadow-lg shadow-indigo-100 shrink-0">
                  {currentUser?.name?.[0]}
                </div>
              </button>
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-hidden relative">
          {activeTab === 'analytics' && <AnalyticsDashboard members={members} />}
          {activeTab === 'kanban' && (
            <KanbanBoard 
              members={members} 
              events={events}
              team={team}
              onMoveMember={moveMember} 
              onAddMember={() => { setSelectedMember(null); setIsMemberModalOpen(true); }}
              onMemberClick={(m) => { setSelectedMember(m); setIsMemberModalOpen(true); }}
              onEditEvent={(e) => { setSelectedEvent(e); setIsEventModalOpen(true); }}
              onAddTask={handleQuickAddTask}
            />
          )}
          {activeTab === 'contacts' && (
            <ContactsModule 
              members={members} 
              team={team}
              onEditMember={(m) => { setSelectedMember(m); setIsMemberModalOpen(true); }}
              onDeleteMember={handleDeleteMember}
              onAddMember={() => { setSelectedMember(null); setIsMemberModalOpen(true); }}
              onQuickTask={handleQuickAddTask}
            />
          )}
          {activeTab === 'agenda' && (
            <ScheduleModule 
              events={events} 
              team={team}
              onAddEvent={() => { setSelectedEvent(null); setIsEventModalOpen(true); }}
              onEditEvent={(e) => { setSelectedEvent(e); setIsEventModalOpen(true); }}
              onDeleteEvent={handleDeleteEvent}
            />
          )}
          {activeTab === 'church' && <ChurchModule churchId={currentUser?.church_id || 'default'} />}
          {activeTab === 'team' && (
            <TeamModule 
              team={team} 
              onSave={handleSaveTeamMember} 
              onDelete={handleDeleteTeamMember} 
            />
          )}
          {activeTab === 'automation' && <AutomationSettings />}
          {activeTab === 'settings' && <SettingsModule />}
        </div>

        <MemberModal 
          isOpen={isMemberModalOpen} 
          onClose={() => { setIsMemberModalOpen(false); setSelectedMember(null); }} 
          onSave={handleSaveMember} 
          initialData={selectedMember} 
          team={team}
          events={events}
          onEditEvent={(e) => { setSelectedEvent(e); setIsEventModalOpen(true); }}
          onDeleteEvent={handleDeleteEvent}
        />
        <EventModal 
          isOpen={isEventModalOpen} 
          onClose={() => { setIsEventModalOpen(false); setSelectedEvent(null); }} 
          onSave={handleSaveEvent} 
          initialData={selectedEvent} 
          team={team}
        />
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { 
  Calendar as CalendarIcon, 
  Clock, 
  MapPin, 
  Plus, 
  ChevronLeft, 
  ChevronRight, 
  CalendarDays,
  User as UserIcon,
  Edit3,
  Trash2
} from 'lucide-react';
import { ScheduleEvent, EventType, SystemUser } from '../types';

interface ScheduleModuleProps {
  events: ScheduleEvent[];
  team?: SystemUser[];
  onAddEvent?: (date?: Date) => void;
  onEditEvent?: (event: ScheduleEvent) => void;
  onDeleteEvent?: (id: string) => void;
}

const ScheduleModule: React.FC<ScheduleModuleProps> = ({ events, team = [], onAddEvent, onEditEvent, onDeleteEvent }) => {
  const [viewDate, setViewDate] = useState(new Date());

  const getEventTypeStyle = (type: EventType) => {
    switch (type) {
      case EventType.SERVICE: return 'bg-indigo-100 text-indigo-700 border-indigo-200';
      case EventType.MEETING: return 'bg-amber-100 text-amber-700 border-amber-200';
      case EventType.EVENT: return 'bg-purple-100 text-purple-700 border-purple-200';
      case EventType.FOLLOW_UP: return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case EventType.VISIT: return 'bg-rose-100 text-rose-700 border-rose-200';
      default: return 'bg-slate-100 text-slate-700 border-slate-200';
    }
  };

  const getEventTypeLabel = (type: EventType) => {
    switch (type) {
      case EventType.SERVICE: return 'Culto';
      case EventType.MEETING: return 'Reunião';
      case EventType.EVENT: return 'Evento';
      case EventType.FOLLOW_UP: return 'Acomp.';
      case EventType.VISIT: return 'Visita';
      default: return 'Geral';
    }
  };

  const getResponsibleName = (id?: string) => {
    if (!id) return null;
    return team.find(t => t.id === id)?.name || 'N/D';
  };

  const nextMonth = () => {
    setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() + 1, 1));
  };

  const prevMonth = () => {
    setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() - 1, 1));
  };

  const monthName = viewDate.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' });

  const daysInMonth = new Date(viewDate.getFullYear(), viewDate.getMonth() + 1, 0).getDate();
  const firstDayOfMonth = new Date(viewDate.getFullYear(), viewDate.getMonth(), 1).getDay();
  const calendarDays = Array.from({ length: 42 }, (_, i) => {
    const day = i - firstDayOfMonth + 1;
    return day > 0 && day <= daysInMonth ? day : null;
  });

  const isToday = (day: number | null) => {
    if (!day) return false;
    const now = new Date();
    return now.getDate() === day && now.getMonth() === viewDate.getMonth() && now.getFullYear() === viewDate.getFullYear();
  };

  const hasEventOnDay = (day: number | null) => {
    if (!day) return false;
    return events.some(e => {
      const d = new Date(e.start_date);
      return d.getDate() === day && d.getMonth() === viewDate.getMonth() && d.getFullYear() === viewDate.getFullYear();
    });
  };

  const currentMonthEvents = events.filter(e => {
    const d = new Date(e.start_date);
    return d.getMonth() === viewDate.getMonth() && d.getFullYear() === viewDate.getFullYear();
  });

  return (
    <div className="p-6 h-full overflow-hidden flex flex-col gap-6 bg-slate-50/50">
      <div className="flex justify-between items-end">
        <div>
          <p className="text-sm text-slate-500 font-medium">Controle de compromissos e atividades da comunidade.</p>
        </div>
        <button 
          onClick={() => onAddEvent?.()}
          className="flex items-center gap-2 px-6 py-3 bg-indigo-600 text-white rounded-xl font-black shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95 text-[10px] uppercase tracking-widest"
        >
          <Plus className="w-4 h-4" /> NOVO AGENDAMENTO
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 flex-1 overflow-hidden">
        <div className="lg:col-span-4 flex flex-col gap-6 overflow-y-auto">
          <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm shrink-0">
            <div className="flex justify-between items-center mb-4">
              <h3 className="font-black text-slate-800 uppercase text-[10px] tracking-widest capitalize">{monthName}</h3>
              <div className="flex gap-1">
                <button onClick={prevMonth} className="p-1 hover:bg-slate-50 rounded-lg text-slate-400"><ChevronLeft className="w-4 h-4" /></button>
                <button onClick={nextMonth} className="p-1 hover:bg-slate-50 rounded-lg text-slate-400"><ChevronRight className="w-4 h-4" /></button>
              </div>
            </div>
            <div className="grid grid-cols-7 gap-1 text-center mb-1">
              {['D','S','T','Q','Q','S','S'].map(d => <span key={d} className="text-[9px] font-black text-slate-300">{d}</span>)}
            </div>
            <div className="grid grid-cols-7 gap-1 text-center">
              {calendarDays.map((day, i) => (
                <button 
                  key={i} 
                  disabled={!day}
                  onClick={() => day && onAddEvent?.(new Date(viewDate.getFullYear(), viewDate.getMonth(), day))}
                  className={`aspect-square flex flex-col items-center justify-center text-[11px] font-black rounded-lg transition-all relative ${day ? 'hover:bg-indigo-50 text-slate-500 cursor-pointer' : 'opacity-0'} ${isToday(day) ? 'bg-indigo-600 text-white shadow-md' : ''}`}
                >
                  {day}
                  {hasEventOnDay(day) && (
                    <span className={`absolute bottom-1 w-1 h-1 rounded-full ${isToday(day) ? 'bg-white' : 'bg-indigo-400'}`}></span>
                  )}
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="lg:col-span-8 bg-white rounded-3xl border border-slate-100 shadow-sm flex flex-col overflow-hidden">
          <div className="px-6 py-4 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
            <div className="flex items-center gap-2">
              <CalendarDays className="w-4 h-4 text-indigo-600" />
              <h3 className="text-sm font-black text-slate-800 uppercase tracking-tight">Atividades Agendadas</h3>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-2">
            {currentMonthEvents.length > 0 ? 
              currentMonthEvents
                .sort((a,b) => new Date(a.start_date).getTime() - new Date(b.start_date).getTime())
                .map(event => (
              <div 
                key={event.id} 
                className="group p-3 bg-slate-50/50 hover:bg-white border border-transparent hover:border-indigo-100 rounded-xl transition-all flex items-center justify-between gap-4"
              >
                <div 
                  onClick={() => onEditEvent?.(event)}
                  className="flex items-center gap-4 flex-1 min-w-0 cursor-pointer"
                >
                  <div className="flex flex-col items-center justify-center bg-white border border-slate-100 rounded-lg w-12 h-12 shadow-sm shrink-0">
                    <span className="text-[8px] font-black text-slate-400 uppercase leading-none">{new Date(event.start_date).toLocaleDateString('pt-BR', {month: 'short'})}</span>
                    <span className="text-base font-black text-slate-800 leading-none mt-0.5">{new Date(event.start_date).getDate()}</span>
                  </div>

                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <span className={`px-1.5 py-0.5 rounded text-[8px] font-black uppercase border ${getEventTypeStyle(event.type)}`}>
                        {getEventTypeLabel(event.type)}
                      </span>
                      <h4 className="font-bold text-slate-800 text-sm truncate">{event.title}</h4>
                    </div>
                    <div className="flex items-center gap-3 mt-1 overflow-hidden">
                      <div className="flex items-center gap-1 text-[10px] text-slate-400 font-bold shrink-0">
                        <Clock className="w-3 h-3" />
                        {new Date(event.start_date).toLocaleTimeString('pt-BR', {hour: '2-digit', minute: '2-digit'})}
                      </div>
                      {event.location && (
                        <div className="flex items-center gap-1 text-[10px] text-slate-400 font-bold truncate">
                          <MapPin className="w-3 h-3 shrink-0" />
                          {event.location}
                        </div>
                      )}
                    </div>
                  </div>
                </div>

                <div className="flex items-center gap-2 shrink-0" onClick={(e) => e.stopPropagation()}>
                  {event.responsible_id && (
                    <div className="hidden sm:flex items-center gap-1 px-3 py-1 bg-indigo-50 text-indigo-600 rounded-lg text-[9px] font-black uppercase shadow-sm">
                      <UserIcon className="w-3 h-3" />
                      {getResponsibleName(event.responsible_id)}
                    </div>
                  )}
                  <div className="flex items-center gap-1">
                    <button 
                      onClick={(e) => { e.stopPropagation(); onEditEvent?.(event); }}
                      className="p-2 text-slate-300 hover:text-indigo-600 transition-all rounded-lg hover:bg-slate-100"
                      title="Editar"
                    >
                      <Edit3 className="w-4 h-4" />
                    </button>
                    <button 
                      onClick={(e) => { 
                        e.stopPropagation(); 
                        e.preventDefault();
                        if(onDeleteEvent) onDeleteEvent(event.id); 
                      }}
                      className="p-2 text-slate-300 hover:text-rose-600 transition-all cursor-pointer rounded-lg hover:bg-rose-50"
                      title="Excluir"
                    >
