      setEvents(updatedEvents);
      KoinoniaDB.saveEvents(updatedEvents); // Persistência forçada imediata

      if (selectedEvent?.id === id) {
        setIsEventModalOpen(false);
        setSelectedEvent(null);
      }
    }
  };

  // CORREÇÃO CRÍTICA: SALVAMENTO DE MEMBRO DA EQUIPE
  const handleSaveTeamMember = (userData: Partial<SystemUser>) => {
    if (userData.id) {
      const updatedTeam = team.map(u => u.id === userData.id ? { ...u, ...userData } as SystemUser : u);
      setTeam(updatedTeam);
      KoinoniaDB.saveUsers(updatedTeam);
    } else {
      const newUser: SystemUser = {
        ...userData,
        id: Math.random().toString(36).substr(2, 9),
        church_id: currentUser?.church_id || 'default',
        permissions: userData.permissions || ['standard'],
      } as SystemUser;
      const updatedTeam = [...team, newUser];
      setTeam(updatedTeam);
      KoinoniaDB.saveUsers(updatedTeam);
    }
  };

  // CORREÇÃO CRÍTICA: EXCLUSÃO DE MEMBRO DA EQUIPE
  const handleDeleteTeamMember = (id: string) => {
    if (window.confirm('Remover este líder da equipe?')) {
      const updatedTeam = team.filter(u => u.id !== id);
      setTeam(updatedTeam);
      KoinoniaDB.saveUsers(updatedTeam); // Persistência forçada imediata
    }
  };

  const handleQuickAddTask = (member: Member) => {
    setSelectedEvent({
      id: '',
      title: `Acomp: ${member.name}`,
      description: `Acompanhamento agendado via pipeline.`,
      type: EventType.FOLLOW_UP,
      start_date: new Date(),
      end_date: new Date(new Date().getTime() + 30 * 60 * 1000),
      member_id: member.id,
      responsible_id: member.responsible_leader_id || currentUser?.id,
      church_id: currentUser?.church_id || 'default',
      created_at: new Date()
    } as ScheduleEvent);
    setIsEventModalOpen(true);
  };

  const moveMember = (id: string, nextStage: MemberStage) => {
    setMembers(prev => prev.map(m => m.id === id ? { ...m, stage: nextStage, last_activity: new Date() } : m));
  };

  if (!isLoggedIn) {
    return <LoginScreen onLogin={handleLoginSuccess} />;
  }

  return (
    <div className="flex h-screen bg-white overflow-hidden font-inter">
      <aside className={`${isSidebarOpen ? 'w-80' : 'w-24'} bg-slate-900 transition-all duration-500 flex flex-col z-50 shadow-2xl relative`}>
        <div className="p-10 flex items-center gap-5">
          <div className="w-12 h-12 bg-indigo-500 rounded-[18px] flex items-center justify-center shadow-lg shadow-indigo-500/30 shrink-0">
            <Shield className="w-6 h-6 text-white" />
          </div>
          {isSidebarOpen && <span className="font-black text-2xl text-white tracking-tight uppercase truncate">Koinonia</span>}
        </div>

        <nav className="flex-1 px-8 py-6 space-y-2 overflow-y-auto scrollbar-hide">
          {navItems.map(item => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-5 px-5 py-4 rounded-[24px] transition-all group ${
                activeTab === item.id 
                  ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/30' 
